programs.sol:
"""Estimate the component's negative 'age / stage' response.

Age and stage word pieces dominate; page, image, range and several -age
endings respond less strongly. Include a few translated age/stage words,
Cyrillic/Japanese sound-alike pieces, and a small response to historical ſ.
This is not a general oldness detector: old, years, average and package are
left at zero. Strength varies with inflection, capitalization and whether a
piece continues another token. Remember one token for split words and the
phrases 'stage of', 'age of' and 'young people'; reset at each document.
"""
READS = ()

AGE = {'age': -3.65, 'ages': -3.1, 'aged': -2.6,
       'aging': -2.15, 'ageing': -1.8, 'ager': -2.45, 'agers': -1.0}
STAGE = {'stage': -4.5, 'stages': -3.6, 'staged': -2.8, 'staging': -3.5}
TRANSLATIONS = {'年龄': -2.5, '时代': -1.7, '阶段': -1.7, '舞台': -1.7,
                '年纪': -0.85, '歳': -0.85, 'edad': -0.85, 'возраст': -0.85}


def response(token, previous):
    word = token.strip().lstrip('._-/([<')
    w, prev = word.lower(), previous.strip().lower()
    upper = word[:1].isupper()
    attached = not token[:1].isspace()
    if w in STAGE:
        value = STAGE[w]
        if w == 'stage' and upper and not attached:
            value -= 0.65
        return value
    if w in AGE:
        if attached and prev.endswith('st'):
            return -4.8                 # st + aged / aging
        if attached and w in ('aged', 'aging'):
            if prev.endswith(('cour', 'our', 'lever', 'aver', 'eng')):
                return -0.9 if w == 'aging' else -1.1
            if prev.endswith(('man', 'pack', 'salv')):
                return -1.9
            return -3.2
        if attached and w == 'age':
            if prev.endswith(('shrink', 'break', 'vis', 'patron')):
                return -2.4
        if w == 'ages' and upper:
            return -2.1
        value = AGE[w]
        if attached and w == 'age':
            value -= 0.3
        if attached and word.isupper():
            value -= 0.65
        if w == 'age' and upper and not word.isupper():
            value -= 0.3
        return value
    if w == 'of':
        if not previous[:1].isspace():
            return 0.0                 # don't treat mont + ages as 'ages of'
        return {'stage': -1.3, 'stages': -1.1, 'age': -0.55,
                'ages': -0.55, 'range': -0.22}.get(prev, 0.0)
    if w == 'people' and prev == 'young':
        return 1.0
    if w in ('image', 'images', 'imaging', 'imagery'):
        if w == 'imaging':
            return -2.0
        if w != 'image':
            return -1.1
        return -1.8 if upper else -1.3
    if w in ('page', 'pages'):
        return -0.95 if w == 'pages' else -1.35 if upper else -1.1
    if w in ('range', 'ranges', 'ranging'):
        return -1.1 if w == 'range' else -0.85
    # Short -age pieces and longer words sharing that ending.
    if w in ('sage', 'mage'):
        return -2.7 if not attached and word.islower() else -3.3
    if w == 'cage':
        return -2.5 if upper else -1.8
    if w in ('rage', 'lage', 'orage', 'ophage'):
        return -2.0 if w == 'rage' else -2.6
    if w in ('village', 'damage', 'damaged', 'usage', 'dosage',
             'massage', 'vintage', 'ilage'):
        return -1.4 - (0.4 if upper or (w == 'usage' and attached) else 0)
    if w in ('villages', 'damages', 'passage', 'passages', 'magazine',
             'magazines', 'agens', 'agement'):
        return -0.9
    if w in ('postage', 'mileage', 'wage', 'wages', 'savage',
             'avage', 'amage', 'amaged'):
        return -1.8
    if w in ('agen', 'agem', 'lagen', 'agento'):
        return -1.2
    if w in ('ange', 'anges', 'anger', 'angers'):
        return -0.55
    if w in TRANSLATIONS:
        return TRANSLATIONS[w]
    # Foreign-script spellings of the 'age' sound, and historical long s.
    if token in ('аж', 'раж', 'ージ', 'ſ'):
        return {'аж': -0.75, 'раж': -1.3, 'ージ': -1.5, 'ſ': -0.68}[token]
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, token), float(response(token, prev))

programs.haiku:
"""Layer 0, MLP down-projection, component 3456: a spelling detector for the letters
"a-g-e", above all in the English word "age" and "stage".

Its activation is negative on these tokens, the more so the closer the token is to the
bare word "age" or "stage":

- "stage" (and any token containing "stage"): about -4.5;
- "age", "ages", "aged", "aging": about -3.6;
- words built around "-age" or "-ange" that are not the word itself, such as "image",
  "page", "range", "village", "damage", "usage", "passage", "postage", "wage", "cage":
  about -1.2;
- a weaker group: "magazine", "race", "racing", "message": about -0.7;
- any other token that merely contains "age" (for example "language", "package",
  "storage"): a small negative, about -0.3.

Every other token predicts 0. This is a list of word forms read off the data, not a model of
meaning: "era", "old" and "years" do not trigger it, but "wage" and "cage" do.
"""

READS = ()

STAGE_WORDS = {"stage", "stages", "staged", "staging"}
AGE_WORDS = {"age", "ages", "aged", "aging"}
IMAGE_LIKE_WORDS = {
    "image", "images", "page", "pages", "range", "ranges", "village", "damage",
    "damages", "damaged", "usage", "passage", "postage", "massage", "dosage",
    "pagination", "vintage", "mileage", "savage", "rage", "cage", "wage", "sage", "mage",
}
WEAK_WORDS = {"magazine", "magazines", "race", "racing", "message"}

STAGE_VALUE = -4.5
AGE_VALUE = -3.6
IMAGE_LIKE_VALUE = -1.2
WEAK_VALUE = -0.7
OTHER_AGE_VALUE = -0.3


def step(carry, prefix, upstream):
    """The component's activation at the newest token, from its spelling and word list."""
    word = prefix.token_strings[-1].strip().lower()
    if word in STAGE_WORDS or "stage" in word:
        return carry, STAGE_VALUE
    if word in AGE_WORDS:
        return carry, AGE_VALUE
    if word in IMAGE_LIKE_WORDS:
        return carry, IMAGE_LIKE_VALUE
    if word in WEAK_WORDS:
        return carry, WEAK_VALUE
    if "age" in word:
        return carry, OTHER_AGE_VALUE
    return carry, 0.0

programs.luna:
"""Give a small negative response to tokens containing 'age' or 'range'.

These spellings catch a conspicuous family of responses in the examples;
other context-dependent responses are left at zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if "age" in token:
        return None, -0.9
    if "range" in token:
        return None, -0.6
    return None, 0.0

programs.sol:
"""Predict negative activity for early n-bearing subword syllables.

Lowercase vowel-n-vowel fragments get the largest values, especially short
-inal/-iner/-anic forms and n-a-t/n-a-r endings. Short n-vowel-consonant
continuations, doubled n, and Cyrillic н syllables get weaker values.
Four-letter sn-onsets allow capitals. The word root nation (with optional
plural s) allows both capitals and spaces. Leading spaces and capitals
otherwise suppress the response.

The only state is whether the preceding token in this document ended in a
letter. This approximates a spelling pattern, not the model's irregular
word-specific strengths or its longer-range contextual variation.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouy')


def fragment_value(raw, continuation):
    original = raw.strip().lower()
    text = ''.join(c for c in unicodedata.normalize('NFD', raw.lower())
                   if not unicodedata.combining(c)).strip()
    if not text or not text.isalpha():
        return 0.0
    if text in ('nation', 'nations'):
        return -0.34
    if raw[:1].isspace():
        return 0.0
    if not raw.islower() and not text.startswith('sn'):
        return 0.0
    if (text.startswith('sn') and len(text) == 4
            and text[2] in VOWELS
            and text[-1] not in VOWELS and text[-1] != 'w'):
        return -0.60
    if original.startswith('н') and len(text) == 3:
        if text[1] in 'аеёиоуыэюя' and text[2] not in 'аеёиоуыэюяй':
            if text[1] == 'о':
                return -0.30
            return -0.05 if text[1] in 'иы' else -0.18
        return 0.0
    n = original.find('n')
    if n < 0 or n > 1 or n + 1 >= len(text):
        return 0.0
    after = text[n + 1:]
    if after[0] not in VOWELS:
        if (n == 1 and after.startswith('n') and continuation
                and 4 <= len(text) <= 5 and text[-1] not in VOWELS):
            return -0.20
        return 0.0
    if n == 1 and text[0] in VOWELS:
        if len(after) == 1:
            return -0.08 if continuation else 0.0
        if after.startswith('a'):
            if len(text) <= 4 or after.startswith(('at', 'ar')):
                return -0.55
            return -0.20 if len(text) <= 6 else 0.0
        if text.endswith('er'):
            return -0.80 if len(text) <= 4 else -0.20
        if text.endswith('ic'):
            return -0.50 if len(text) <= 4 else -0.20
        if len(text) <= 6:
            return -0.27 if continuation else -0.10
        return 0.0
    if n == 0 and continuation:
        if (3 <= len(text) <= 4 and text[-1] not in VOWELS
                and all(c not in VOWELS and c != 'w' for c in after[1:])):
            value = -0.32
            if after[0] == 'a':
                value -= 0.10
            elif after[0] == 'i':
                value += 0.10
            if text[-1] == 'r':
                value -= 0.10
            elif text[-1] in 'stw':
                value += 0.10
            return value
        return -0.05 if len(text) <= 4 else 0.0
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    continuation = (carry is not None and carry[0] == doc and carry[1])
    value = fragment_value(raw, continuation)
    return (doc, raw[-1:].isalpha()), float(value)

programs.luna:
"""Predict the component's positive response to three common quantifiers.

It marks “all,” “each,” and “both,” with “each” receiving the strongest
prediction; every other token predicts zero.
"""

READS = ()

_QUANTIFIER_OUTPUT = {"all": 0.78, "each": 1.10, "both": 0.78}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, float(_QUANTIFIER_OUTPUT.get(word, 0.0))

programs.sol:
"""A surface-form detector for 'in', modulated by common collocations.

Separators and capitalization strengthen the response; word-internal
lowercase 'in' is weaker. Selected result/involvement/containment phrases
weaken ' in', while variation nouns strengthen it. The related membership
symbol and 'wherein/herein/therein' receive smaller responses.
Document starts have separate calibration; state resets at each document.
"""
import re

READS = ()
IN_COMPLEMENTS = {
    'result', 'results', 'resulted', 'resulting', 'involved',
    'engage', 'engaged', 'engaging', 'interested', 'enclosed',
    'embedded', 'immersed', 'grounded', 'rooted', 'contained',
    'included', 'stored', 'dissolved',
}
VARIATION_NOUNS = {
    'change', 'changes', 'difference', 'differences', 'increase',
    'increases', 'decrease', 'decreases', 'reduction', 'reductions',
}
INITIAL_FORMS = {' in': 1.92, ' In': 2.56, 'In': 3.01, 'in': 1.27}


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    tail = '' if first else carry[1]
    spelling, leading = token[-2:], token[:-2]
    value = 0.0
    if spelling in {'in', 'In', 'IN'} and not any(
        ch.isalnum() for ch in leading
    ):
        if spelling == 'In':
            value = 1.87 if not leading or leading.isspace() else 1.55
        elif spelling == 'IN':
            value = 1.53 if leading else 0.45
        elif leading:
            value = 1.43
        else:
            value = 0.35 if tail and tail[-1].isalpha() else 1.12
        if token == ' in':
            match = re.search(r'[A-Za-z]+$', tail)
            word = match[0].lower() if match else ''
            if word in IN_COMPLEMENTS:
                value = 0.77
            elif word in VARIATION_NOUNS:
                value = 1.80
        if first:
            value = INITIAL_FORMS.get(token, value)
    elif token.strip() == '∈':
        value = 0.80
    elif token == ' wherein':
        value = 0.83
    elif token in {' herein', ' therein'}:
        value = 0.40
    return (doc, (tail + token)[-48:]), value

"""A lexical approximation to a nature/type/quality feature.

性 and Korean 성 can name nature or sex, or nominalize a quality. English
quality nouns and adjective vocabularies, and abstract-noun suffix fragments,
are weaker cues. All rules inspect only the current token; other tokens give 0.
"""
import re
from functools import lru_cache

READS = ()
QUALITY_NOUNS = set('''quality qualities characteristic characteristics
    personality personalities reliability stability flexibility durability
    sensitivity specificity variability scalability toxicity authenticity
    integrity productivity creativity elasticity conductivity profitability
    competitiveness complexity availability accessibility confidentiality
    transparency consistency correctness usefulness uniqueness openness
    toughness effectiveness efficiency accuracy sustainability'''.split())
PROPERTY_ADJECTIVES = set('''elastic linear quadratic cubic exponential nonlinear
    acidic spherical permanent persistent selective reactive responsive
    repetitive inherent inherently resistant sensitive aggressive'''.split())
NOMINAL_FRAGMENTS = set('''ness eness iness leness iveness fulness
    ability ibility ility ality icity idity inity ity ivity ativity
    arity ularity osity ogeneity ency'''.split())


@lru_cache(maxsize=65536)
def lexical_value(token):
    s = token.strip()
    w = s.lower().strip('._-()/\\,:;')
    if s == '性':
        return 6.6
    if s in {'性和', '性的', '性与', '性與', '性及'}:
        return 5.3
    if '性' in s:
        if s in {'属性', '屬性', '性能', '性命'}:
            return 1.25
        if s.endswith('性') and not s.startswith('的'):
            return 2.0 if s in {'女性', '男性'} else 3.3
        return 1.9
    if s == '성':
        return 5.9
    if s.startswith('성') and s[1:] in {'을', '이', '의', '은', '과', '도', '에'}:
        return 4.7
    if s == '型':
        return 1.2
    if s in {'色', '质', '質', '质量', '質量', '品质', '品質', '类', '類'}:
        return 0.7
    if w == 'nature' or w.startswith('характер'):
        return 1.5
    if w in {'sexuality', 'responsiveness'}:
        return 1.8
    if w in {'sex', 'sexual', 'sexually', 'sexo', 'sexe', 'gender', 'genders'}:
        return 1.0
    if w in {'typeerror', 'isinstance'} or s in {'Type', '-type'}:
        return 0.8
    if w == 'type' or re.search(r'(Type|_type|\.type)$', s):
        return 0.57
    if w == 'types' or s.endswith('Types'):
        return 0.38
    if w == 'property':
        return 0.3
    if w == 'properties' or w.startswith('качеств') or w in QUALITY_NOUNS:
        return 0.78
    if w in {'chronic', 'inflammatory'}:
        return 1.15
    if w in PROPERTY_ADJECTIVES:
        return 0.75
    if w in {'permanently', 'selectively', 'creatively'}:
        return 1.0
    if w.endswith(('ность', 'ностью')):
        return 0.55
    if w.endswith('ности'):
        return 0.3
    if token == s and s.islower() and w in NOMINAL_FRAGMENTS:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    return None, float(lexical_value(prefix.token_strings[-1]))

programs.haiku:
"""Layer-0 MLP unit 3462 (down_proj): a "quality / nature" word detector.

The unit reads the current token, and fires on words that name a quality, property or
nature of something. Its strongest trigger is the Chinese character 性 (xìng), which
means "-ness / -ity / nature" (e.g. 灵活性 "flexibility", 特性 "characteristic") and also
"sex" (性别, 性感). Korean 성 (the same Sino-Korean morpheme) fires as strongly. English
triggers are weaker: "nature" itself, "of" right after "nature" ("the nature of"), other
quality words (quality, characteristic, sexual, gender), "type"/"property", and words
ending in -ity, -ness, -ility, -ivity (sensitivity, reliability, stability).

Predicted activation = the strength of that trigger at the current token.
"""

READS: tuple[str, ...] = ()

SEX_WORDS = {"sex", "sexual", "gender", "sexuality"}
QUALITY_WORDS = {
    "quality", "qualities", "characteristic", "characteristics", "linear", "elastic",
    "chronic", "inflammatory", "reactive", "aggressive", "persistent",
}
TYPE_WORDS = {"type", "types", "property", "properties"}
NOT_QUALITY = {"city", "entity", "community", "university", "activity", "probability",
               "business", "capacity", "availability", "security", "density", "velocity"}
QUALITY_SUFFIXES = ("ity", "ness", "ility", "ivity", "ability")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    word = tok.lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if tok in ("性", "성"):
        value = 6.0          # the bare morpheme
    elif "性" in tok or "성" in tok:
        value = 2.5          # compounds: 灵活性, 特性, 性感, 女性 ...
    elif word == "nature":
        value = 1.5
    elif word == "of" and before == "nature":
        value = 1.0          # "the nature of"
    elif word in SEX_WORDS or word in QUALITY_WORDS:
        value = 0.9
    elif word in TYPE_WORDS or word.endswith("type") or word == "型":
        value = 0.5
    elif word.endswith(QUALITY_SUFFIXES) and word not in NOT_QUALITY:
        value = 0.3
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A lexical detector for roll/volume (Chinese 卷, Japanese 巻).

It recognizes the corresponding English word families: rolling, volumes,
involvement, convolution, questionnaires, and bundles. Inflections and
word-initial versus interior fragments have different fitted strengths.
It scores the shared, incomplete UTF-8 prefixes used by 巻 and 捲
(including unrelated kanji with those prefixes), and the related
volume/voucher characters 券 and 권, and rolling/book-count characters.
A small echo persists on a following “of”, within the same document.
Other text has zero response.
"""

READS = ()

# Tokenizer pieces for the first two UTF-8 bytes of rolling characters:
JAPANESE_ROLL_PREFIX = 17156  # bytes E5 B7: first two bytes of 巻
TRADITIONAL_ROLL_PREFIX = 14675  # bytes E6 8D: first two bytes of 捲

INVOLVEMENT = {
    'involve': 0.63, 'involves': 0.58, 'involved': 0.95,
    'involving': 0.46, 'involvement': 0.70, 'invol': 0.80,
    'inv': 0.75,
}
ROLLING = {
    'roll': 0.98, 'rolls': 0.88, 'rolled': 0.92,
    'rolling': 0.78, 'roller': 0.60, 'rollers': 0.80,
    'rollout': 0.49, 'enroll': 0.70, 'enrol': 0.70,
    'enrolled': 0.43, 'scroll': 0.59, 'scrollbar': 0.49,
    'scrolltop': 0.80, 'curl': 0.40, 'curls': 0.34,
    'winding': 0.26, 'coil': 0.18, 'coils': 0.24,
    'reel': 0.30, 'reels': 0.30, 'rotary': 0.35,
}


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    token = int(prefix.token_ids[-1])
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = piece.strip().lstrip('._-(/')
    word = raw.lower()
    initial = piece.startswith(' ')
    value = 0.0
    if piece == '卷':
        value = 6.0
    elif '卷' in piece:
        value = 2.1
    elif piece == '券':
        value = 1.28
    elif piece in ('滚', '滾', '冊', '册', '刊'):
        value = 0.70 if piece == '刊' else 0.40
    elif word == '권':
        value = 0.80
    elif token == JAPANESE_ROLL_PREFIX:
        value = 2.73
    elif token == TRADITIONAL_ROLL_PREFIX:
        value = 1.35
    elif '\ufffd' in piece or piece in ('巻', '捲'):
        ending = prefix.text_prefixes[-1][-1:]
        value = {'巻': 4.8, '捲': 3.9}.get(ending, 0.0)
    elif word in INVOLVEMENT:
        value = INVOLVEMENT[word]
        if word == 'inv' and raw == 'Inv' and initial:
            value = 1.05
    elif word in ROLLING:
        value = ROLLING[word]
        if not initial and word in ('roll', 'rolled', 'rolling'):
            value -= 0.28
            if previous.lower().endswith('cont'):
                value = 0.35
    elif word in ('volume', 'volumes', 'volum', 'olume', 'olumes'):
        value = 0.82 if word == 'volume' else 0.60
        if word == 'volume' and raw == 'Volume' and initial:
            value = 1.0
        elif word == 'volume' and piece == 'volume':
            value = 0.95
        elif word == 'volume' and piece.startswith('_'):
            value = 0.65
    elif word in ('vol', 'voll'):
        value = 0.45 if word == 'vol' else 0.70
    elif word == 'conv':
        value = 1.68 if initial and raw == 'conv' else 0.95
    elif word.startswith('convol'):
        value = 1.0
    elif word == 'cnn':
        value = 0.43
    elif word in ('questionnaire', 'questionnaires', 'naire', 'naires'):
        value = 0.95 if word.startswith('question') else 0.40
    elif word in ('bundle', 'bundles', 'undle'):
        value = 0.55
        if raw == 'Bundle':
            value = 1.2 if piece.startswith(('.', '(')) else 0.75
    if word == 'of' and carry is not None and carry[0] == doc:
        value += 0.25 * carry[2]
    return (doc, piece, value), float(value)

"""A local detector for chronology, age, and successive versions.

The strongest negative estimates complete phrases such as 'recent years',
'future generations', 'new version', and 'years old'. Temporal modifiers
multiply a small lexicon of time/age/change words. There are analogous Chinese
and Japanese expressions. A negative phrase weakly persists on linking words.
Present-value expressions such as 'current ratio' have the opposite sign.
Other tokens are mostly zero; some temporal words and chat boundaries have
small lexical offsets. State resets at every document boundary.
"""
READS = ()


def lexicon(groups):
    return {word: weight for weight, words in groups for word in words.split()}


MODIFIER = lexicon([
    (1.1, 'recent newer'),
    (1.0, 'future'),
    (0.85, 'early earlier earliest later past previous current latest newest'),
    (0.7, 'new modern ancient updated ongoing subsequent'),
    (0.45, 'next first last present prior old older younger'),
    (0.3, 'late second long final initial'),
])
TIME_WORD = lexicon([
    (1.45, 'version old'),
    (1.8, 'older'),
    (1.35, 'history historic past generations'),
    (1.1, 'versions generation years stage stages step today'),
    (0.9, 'age childhood born modern'),
    (0.8, 'year date dates decade decades centuries developments changes updates'),
    (0.6, 'steps release releases edition editions development iteration'),
    (0.5, 'life time times day days week weeks month months century era'),
    (0.4, 'studies'),
    (0.25, 'study research'),
])
TIME_UNIT = set('year years month months days decade decades century centuries'.split())
CJK_MODIFIER = set((
    '新 最新 新的 的新 老 旧 舊 今 早期 后期 後期 未来 未來 '
    '过去 過去 过去的 现在 現在 目前 当前 當前 年轻 年輕 '
    '以前 以往 悠久 更新'
).split())


def phrase(previous, word):
    value = -MODIFIER.get(previous, 0.0) * TIME_WORD.get(word, 0.0)
    if previous in TIME_UNIT:
        if word in {'old', 'older'}:
