READS = ()

# Nouns for spans of time, ages, versions, stages and dates.
TIME_WORDS = {
    "year", "years", "old", "-old", "age", "ages", "decade", "decades", "century",
    "centuries", "era", "eras", "generation", "generations", "stage", "stages",
    "version", "versions", "history", "date", "dates", "edition", "updated",
    "upgrade", "anniversary", "birthday", "past", "older", "oldest", "month",
    "months", "day", "days", "time", "times",
}
# Words that say how recent, new, current or future the following noun is.
RECENCY_WORDS = {
    "recent", "recently", "latest", "future", "newer", "newest", "new", "newly",
    "last", "previous", "early", "later", "upcoming", "current", "modern", "next",
    "coming", "past", "older", "younger", "ancient", "old", "young", "aged",
}
# Span-of-time words that come right before "old" in "N years old".
AGE_SPAN_WORDS = {"year", "years", "-year", "day", "days", "month", "months", "week", "weeks"}
# Forward-looking words with a small positive response.
FORWARD_WORDS = {"after", "before", "coming", "upcoming", "near", "latest", "modern", "zone", "progress"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if word in ("old", "-old") and before in AGE_SPAN_WORDS:
        value = -0.9  # "10 years old"
    elif word in TIME_WORDS and before in RECENCY_WORDS:
        value = -0.5  # "recent years", "latest version"
    elif word in TIME_WORDS:
        value = -0.05
    elif word == "of" and before in TIME_WORDS:
        value = -0.1  # "history of", "decades of"
    elif word == "</think>":
        value = 0.33
    elif word in FORWARD_WORDS:
        value = 0.07
    else:
        value = 0.0
    return carry, float(value)

