"""Respond to a Latin letter-fragment fused to punctuation or a tab.

A single capital after '-' or '/' is strongest. Preceding words strengthen
it; preceding single letters or all-cap abbreviations weaken it. Vowels and
coordinate letters get lower estimates. Longer identifiers are mostly quiet,
with small responses to capitalized fragments and unspaced sentence starts.
The constants summarize character/word classes, not vocabulary entries.
"""
import re

READS = ()
MARKS = frozenset('-/._(,[<>=+:*&\"\'\t')
SENTENCE_STARTERS = frozenset('''
The This That These Those It Its Is In At As And But Or If We You He She They
There Here However Therefore How What When Where Why Which Who All So For
'''.split())
FUNCTION_WORDS = frozenset('''
in on at to of by as is be do or so an no if it he me we my us up go
'''.split())


def fragment(mark, letters, word, space):
    cap = letters[0].isupper()
    n = len(letters)
    if n == 1:
        if mark == '.' and (word.lower(), letters) in {('i', 'e'), ('e', 'g')}:
            return 0.89  # i.e. and e.g.
        if mark in '-/':
            value = 2.1 if cap else 0.84
        elif mark == '.':
            value = 1.13 if cap else 0.43
        elif mark in '*&\"\'\t':
            value = 0.90 if cap else (0.03 if mark in "&'" else 0.36)
        else:
            value = 1.25 if cap else 0.38
        if letters.lower() in 'aeiou':
            value -= 0.33 if cap else 0.30
        elif letters.lower() in 'xyz':
            value -= 0.51 if cap else 0.30
        if mark != '.' or cap:
            length = len(word)
            gain = 1.0 + 0.28 * min(length, 8) / 8
            if length == 1:
                gain -= 0.40
            elif length > 1 and word.isupper():
                gain -= 0.28
            elif length == 0:
                gain -= 0.04
            value *= gain + (0.61 if space else 0.0)
        return value
    if mark == '.' and letters in SENTENCE_STARTERS:
        return 1.05
    if cap:
        short = n <= 3
        if mark in '-/':
            return (0.73 if short else 0.26) if letters.isupper() else (
                1.12 if short else 0.66)
        if mark == '_':
            return (0.11 if short else -0.08) if letters.isupper() else (
                0.85 if short else 0.62)
        return (0.35 if short else 0.10) if letters.isupper() else (
            0.50 if short else 0.25)
    if mark in '-/' and n == 2 and letters not in FUNCTION_WORDS:
        return 0.21
    return -0.07 if mark in '(_' and n >= 3 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word, space = ('', False) if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.0
    if (len(s) > 1 and s[0] in MARKS
            and s[1:].isascii() and s[1:].isalpha()):
        value = fragment(s[0], s[1:], word, space)
    if s.isascii() and s.isalpha():
        word = (word + s)[-20:]
    else:
        tail = re.search(r'[A-Za-z]+$', s)
        word = tail.group()[-20:] if tail else ''
    return (doc, word, bool(s) and s[-1].isspace()), float(value)

"""A negative response to unfinished UTF-8 character pieces.

A replacement-marked character start after a space gets the largest response,
especially in Chinese/Japanese text. A piece that extends but does not finish
an earlier character gets a smaller response; completing it gives zero.
The script of the most recent decoded non-ASCII letter supplies context when
an unfinished character's own script cannot yet be read. Other tokens give
zero. State resets at document boundaries.
"""
READS = ()


def update_script(cjk, text):
    for c in text:
        if '\u3400' <= c <= '\u9fff' or '\u3040' <= c <= '\u30ff':
            cjk = True
        elif ord(c) > 127 and c.isalpha():
            cjk = False
    return cjk


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        cjk, previous_fragment = False, False
    else:
        _, cjk, previous_fragment = carry
    token = prefix.token_strings[-1]
    cjk = update_script(cjk, token)
    fragment = token.endswith('\ufffd')
    value = 0.0
    if fragment:
        text = prefix.text_prefixes[-1]
        if not text.endswith('\ufffd'):
            cjk = update_script(cjk, text[-1:])
        elif previous_fragment and len(text) == len(prefix.text_prefixes[-2]):
            value = -1.15
        elif token.startswith(' '):
            value = -5.1 if cjk else -2.55
        elif token.strip('\ufffd'):
            value = -0.95
        else:
            value = -2.6 if cjk else -0.95
    return (doc, cjk, fragment), value

