"""Estimate a negative signal for words about permission and capability.

Allowing words carry the strongest signal; related permission, prevention,
requirement, and enabling words get smaller estimates. Everything else is zero.
"""
import re

READS = ()
ABILITY = re.compile(r"\b(?:un)?able\b")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].lower()

    if "allow" in word:
        value = -7.9
    elif any(stem in word for stem in ("permit", "forbid", "prohibit")):
        value = -2.2
    elif any(stem in word for stem in (
        "permiss", "accept", "deny", "refus", "approv", "admit",
    )):
        value = -0.9
    elif any(stem in word for stem in ("prevent", "require", "enabl")):
        value = -0.8
    elif any(stem in word for stem in ("cause", "offer", "invite", "encourag")):
        value = -0.6
    elif "owing" in word or ABILITY.search(word):
        value = -0.3
    else:
        value = 0.0
    return None, float(value)

