"""Unspaced operators and separators, conditioned on what they attach to.

Negative responses are strongest after word-like tokens, somewhat weaker
after numbers, and usually absent after whitespace. Opening code blocks and
column-separating tabs also respond. A word-start token receives a small
attachment bonus. Only the current and previous tokens are used; ordinary
text is approximated by zero.
"""
from functools import lru_cache

READS = ()

# Magnitude after a number, after one letter, and growth with word length.
STRENGTH = {
    '=': (1.27, 1.50, 0.22),
    '+': (1.29, 1.44, 0.16),
    '/': (0.90, 1.12, 0.07),
    '-': (0.72, 0.75, 0.05),
    '—': (2.08, 1.98, 0.16),
    '–': (0.70, 0.66, 0.08),
    '−': (0.96, 1.03, 0.15),
    '<': (0.72, 0.94, 0.14),
    '>': (0.48, 0.46, 0.01),
    '^': (0.70, 0.65, 0.025),
    '*': (0.65, 0.65, 0.025),
    '|': (1.60, 1.55, 0.10),
    '~': (0.74, 0.74, 0.09),
    '×': (1.00, 1.10, 0.10),
    '≈': (0.94, 0.89, 0.10),
    '≠': (0.86, 0.92, 0.12),
    '·': (1.08, 1.11, 0.08),
    '&': (0.52, 0.55, 0.03),
    '(': (0.44, 0.44, 0.01),
    '[': (0.27, 0.35, 0.03),
    '\t': (1.16, 1.17, 0.02),
    '\xa0': (1.19, 1.22, 0.07),
    '\x00': (1.03, 0.83, 0.0),
    '\\': (0.23, 0.24, 0.01),
    '→': (0.93, 0.90, 0.04),
    '==': (1.16, 1.20, 0.08),
    '!=': (1.36, 1.45, 0.10),
    '<=': (0.97, 1.00, 0.04),
    '>=': (0.76, 0.78, 0.03),
    '<<': (1.43, 1.42, 0.04),
    '||': (1.05, 1.10, 0.07),
    '--': (1.02, 1.10, 0.04),
    '++': (0.14, 0.35, 0.03),
    '->': (0.16, 0.19, 0.01),
}


def attached(mark, previous):
    number, letter, growth = STRENGTH[mark]
    if not previous:
        return -0.5 * number
    last = previous[-1]
    if last.isspace():
        if mark in {'–', '−', '→', '\x00', '\\', '->'}:
            return 0.2
        if mark == '^':
            return -0.45
        return -0.1 if mark in {'\xa0', '—'} else 0.0
    if last.isdigit():
        return -number
    if last.isalpha():
        if not last.isascii():
            return -0.9 * number
        length = 0
        for char in reversed(previous):
            if not char.isalpha():
                break
            length += 1
        length += 2 * previous[0].isspace()
        return -letter - growth * min(4, length - 1)
    if mark == '[':
        return 0.1
    if mark in {'\\', '->'}:
        return 0.04
    if mark in {'<', '('}:
        return -0.1
    if mark == '\xa0':
        return -0.85 if last in '.,:;)]}' else -0.6
    factor = 0.55 if mark in {'=', '+'} else 0.4
    return -number * factor * (0.4 if last in '([{' else 1.0)


@lru_cache(maxsize=32768)
def response(text, previous):
    if text in STRENGTH:
        return attached(text, previous)
    if text and set(text) <= set('\t\r\n') and '\t' in text:
        value = attached('\t', previous)
        if '\n' in text:
            return value * 0.8
        return value * 0.75 - 0.12

    # Braces opening a block, rather than an inline object or a TeX argument.
    bare = text.rstrip('\r\n')
    if bare.endswith('{') and all(c in ' ()[]{}+-' for c in bare):
        if '\n' in text:
            if ')' in bare:
                return -1.28
            return -0.5 if text.startswith(' ') and '\r' not in text else -0.75
        if bare == '{':
            if previous.strip() in {'begin', 'end'}:
                return -0.14
            return -0.62 if previous and previous[-1].isalnum() else -0.15
        return -0.88 if not text.startswith(' ') and ')' in text else -0.1
    if text.startswith(' '):
        return 0.0

    # Assignment followed immediately by an opening delimiter.
    if text in {'={', '=(', '=\\'}:
        factor = 0.3 if text == '=(' else 0.5
        return factor * attached('=', previous)

    # Closing brackets joined to an operator retain a reduced response.
    if len(text) > 1 and text[-1] in '=+-/*^|—':
        if all(c in ')]}."' for c in text[:-1]):
            if text[-1] == '-':
                return -0.77
            mark = text[-1]
            return -0.98 if mark == '=' else -0.78 * STRENGTH[mark][0]
    if text == '**':
        return -0.2 if previous and previous[-1].isspace() else 0.6
    if text in {'/\n', '/\n\n'}:
        return 0.65 * attached('/', previous)
    if text == '|\n':
        if not previous or previous[-1].isspace():
            return -0.4
        return min(-1.25, attached('|', previous))
    if text == '(\n':
        return attached('(', previous)
    return 0.0


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, text), float(response(text, previous))

