"""Opening parentheticals and some short grammatical word completions.

A space-plus-parenthesis fires after names/content words, less after
function words, and hardly at all after code controls or math operators.
There are additional responses to Greek letters/endings and to common
Greek, Persian, Hindi and Thai grammatical words as they are spelled out.
A PHP opening tag is another recognized formatting continuation.
The constants are approximate training means, not token-ID lookups.
"""

import unicodedata as ud

READS = ()
FUNCTION_WORDS = set('''a an the and or but of to in on at by for from with
as is are was were be been being that this it not'''.split())
CODE_CONTROLS = set('if while for switch return assert elif else'.split())
GREEK_VOWELS = set('αεηιουω')
# Conjunctions, prepositions, articles, pronouns, and the copula.
GREEK_WORDS = {
    'και': 3.3, 'για': 3.3, 'από': 3.5, 'που': 3.35,
    'να': 2.6, 'αν': 1.95, 'με': 1.75, 'σε': 1.9,
    'της': 2.35, 'τις': 2.35, 'τους': 2.2, 'του': 1.93,
    'το': 1.65, 'την': 1.52, 'των': 1.6, 'τα': 1.85,
    'τον': 1.34, 'οι': 1.45, 'μια': 2.05,
    'σου': 1.55, 'σας': 1.96, 'μας': 1.3, 'είναι': 1.58,
    'στην': 1.27, 'στα': 1.33, 'στο': 0.93, 'στις': 1.85,
}
# Article stems and productive prepositional prefixes, before completion.
GREEK_STEMS = set('τη τι τω στ δι γι απ πρ κα εν ανα συν δια κατα'.split())
# Persian link words, postpositions, pronouns, and auxiliary verb stems.
PERSIAN_WORDS = {
    'که': 1.95, 'را': 1.63, 'از': 1.45, 'پر': 2.06,
    'تا': 1.36, 'آن': 0.69, 'برای': 0.87, 'اگر': 0.86,
    'هم': 0.41, 'یا': 0.5, 'شما': 0.74,
    'کن': 1.18, 'کر': 1.27, 'کرد': 1.64,
}
# Hindi postpositions, conjunctions and forms of "be".
HINDI_WORDS = {
    'के': 5.7, 'से': 5.5, 'को': 4.7, 'की': 4.0, 'का': 3.9,
    'कि': 3.5, 'पर': 2.4, 'कर': 1.9, 'हो': 2.2,
    'है': 4.2, 'हैं': 2.34, 'में': 5.94, 'और': 3.7,
}


def final_word(text):
    word = ''
    for char in reversed(text):
        if char.isalpha() or ud.category(char).startswith('M'):
            word = char + word
        else:
            break
    return word[-40:]


def parenthesis(previous):
    word = previous.strip()
    if not word:
        return 0.25
    if word in CODE_CONTROLS:
        return 0.06
    if word in FUNCTION_WORDS:
        return 0.17
    if word.endswith('='):
        return -0.10
    if word.endswith(('(', '[', '+', '-', '/', '*')):
        return 0.04
    if word.endswith((',', ':', ';')):
        return 0.13
    if word[-1].isdigit():
        return 0.43
    if any(c.isupper() for c in word):
        return 0.57
    if word[-1].isalpha():
        return 0.50
    return 0.33


def greek(token, word):
    base = ud.normalize('NFD', token.strip())[0].lower()
    value = 0.65 if base in GREEK_VOWELS else 0.20
    if token.startswith(' ') or len(word) <= 1:
        value *= 0.3
    elif token == 'ν':
        value = 0.90
    elif token == 'ς':
        value = 1.40
        if word.endswith(('ες', 'ές', 'ης', 'ής', 'ις')):
            value = 2.10
    if word in GREEK_STEMS:
        value = 1.05
    return GREEK_WORDS.get(word, value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, word = '', ''
    if carry is not None and carry[0] == document:
        _, previous, word, document_start = carry
    else:
        document_start = (len(prefix.text_prefixes[-2])
                          if prefix.position else 0)
    token = prefix.token_strings[-1]
    word = final_word(word + token)
    if '\ufffd' in token:
        # Recover characters whose UTF-8 bytes straddle token boundaries.
        text = prefix.text_prefixes[-1][document_start:]
        word = final_word(text[-100:])
    lower = word.lower()
    value = 0.002
    if token == ' (':
        value = parenthesis(previous) if previous else 0.03
    elif token == '（':
        value = 0.33
    elif token == '(\\':
        value = 0.22
    elif token == ' (!':
        value = -0.31
