            value = 2.1  # Thai relative/locative particle.
        elif token == '็' and word.endswith('ก็'):
            value = 1.45  # Thai linking particle.
        elif token == 'php' and previous.endswith('<?'):
            value = 2.05
    return (document, token, word, document_start), float(value)

