"""Candidate 3: open brackets after a word, and Greek word-internal pieces.

The component is a "Greek word-continuation / open-parenthesis" feature:
  * an opening parenthesis after a word (" (" or the fullwidth "（") fires at about 0.45,
    and about 0.2 after punctuation;
  * a piece of a Greek word that continues the word (the previous token is also Greek,
    and this token has no leading space) fires strongly when it is a vowel or a final
    sigma (e.g. the "αι" of "και", "ου" of "του", "ς" of "της"), and moderately for
    consonants;
  * a Greek piece that starts a fragment after non-Greek text fires weakly;
  * everything else is about zero.
"""

READS = ()

# Greek letters: basic block and extended (polytonic) block.
GREEK_VOWELS = set("αεηιουωάέήίόύώΑΕΗΙΟΥΩ" "ὰὲὴὶὸὺὼἀἐἠἰὀὐὠἁἑἡἱὁὑὡ")
FINAL_SIGMA = "ς"
OPEN_BRACKETS = {" (", "（"}


def is_greek(ch):
    return "Ͱ" <= ch <= "Ͽ" or "ἀ" <= ch <= "῿"


def has_greek(text):
    return any(is_greek(ch) for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token in OPEN_BRACKETS:
        # an opening bracket right after a word fires more than one after punctuation
        if before.rstrip()[-1:].isalnum():
            return None, 0.45
        return None, 0.2
    if has_greek(token) and not token.startswith(" "):
        if has_greek(before):
            letters = [ch for ch in token if is_greek(ch)]
            if any(ch in GREEK_VOWELS or ch == FINAL_SIGMA for ch in letters):
                return None, 0.9
            return None, 0.5
        return None, 0.2
    return None, 0.0

programs.luna:
"""Use small positive pulses for two opening-round-parenthesis cues.

The token " (" has a recurring positive response in sampled activations;
give the fullwidth opening parenthesis a smaller pulse. Other tokens get
zero, leaving context-dependent variation and other responses unmodeled.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " (":
        return None, 0.4
    if token.strip().startswith("（"):
        return None, 0.3
    return None, 0.0

"""Mark record fields and other short, structured text transitions.

Entity-style relation labels and test status labels often carry a strong
negative activation. Colons, semicolons, and long dashes also introduce new
phrases or fields, so give those beginnings a smaller negative value.
"""
READS = ()

ENTITY_FIELDS = frozenset({
    "instance", "located", "place", "occupation", "currency",
    "member", "country", "educated", "given",
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    before = "" if carry is None or carry[1] != doc else carry[0]
    word = token.strip().casefold()
    ending = before.rstrip()

    if word in ENTITY_FIELDS:
        value = -0.4
    elif word == "pass" and ending.endswith("---"):
        value = -0.45
    elif word == "run" and ending.endswith("==="):
        value = -0.25
    elif ending.endswith(":"):
        value = -0.07
    elif ending.endswith(";"):
        value = -0.055
    elif ending.endswith(("—", "–")):
        value = -0.2
    else:
        value = 0.0

    return ((before + token)[-48:], doc), float(value)

