"""Head noun of a two-word noun compound, e.g. "user[ group]", "customer[ service]",
"patient[ groups]", "population[ growth]", "lymphocyte[ count]", "Visitor[ Center]".

The component is sparse: it fires on the second word of a noun compound, when the word
before it is a noun modifier and the word just read is a common head noun that ends such
phrases. Everywhere else it is close to zero. Chinese two-character nouns (e.g. 人|群,
员工|培训, 学生|干部) also give a positive response; this program only handles the
English head-noun list plus a few Chinese ones.
"""

READS = ()

HEAD_NOUNS = {
    "group", "groups", "user", "users", "data", "service", "services", "status",
    "count", "accounts", "account", "IDs", "ID", "satisfaction", "protection",
    "growth", "pool", "info", "center", "population", "relationship", "training",
    "association", "size", "level", "class", "system", "cadre", "expectations",
    "time", "age", "name", "rate", "number", "history", "care", "support",
}

CHINESE_HEADS = {"群", "培训", "协会", "关系", "干部", "时代", "数", "际", "们"}

ON_VALUE = 0.05


def _is_english_word(s):
    return s.strip().isalpha() and s.strip().isascii()


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip()
    if cur in HEAD_NOUNS and _is_english_word(prev):
        return carry, ON_VALUE
    if cur in CHINESE_HEADS and prev and "一" <= prev[-1] <= "鿿":
        return carry, ON_VALUE
    return carry, 0.0

programs.sol:
"""Tool boundaries and a small family of lexical completions.

Emit a strong pulse at </tool_response>, and on 'reason(s) why/for'.
Other positive pulses recognize selected status/state compounds, abstract
word derivations (purposeful, truthfully, methodological), and familiar
stock phrases. Matching ignores case and leading word separators.
Only completions split across tokens are modeled. The low-amplitude,
token-specific background is left at zero. Reset history at each document.
"""
READS = ()

BOUNDARIES = {
    '</tool_response>': 1.02, '<tool_response>': 0.09,
    '</tool_call>': 0.095, '<tool_call>': -0.10,
    '<|im_start|>': -0.03, '<|im_end|>': 0.028,
    '</think>': -0.09, '\r': 0.13,
}
REASON_CONNECTIVES = {'why': 1.97, 'for': 1.29, 'behind': 1.0, 'to': 0.44}
STOCK_PHRASES = {
    ('subject', 'matter'), ('time', 'zone'), ('vice', 'versa'),
    ('type', 'script'), ('types', 'cript'), ('void', 'main'),
}


def piece(token):
    return token.strip().lstrip('/._-(\'"').casefold()


def completion(head, ending):
    if head in {'reason', 'reasons'}:
        if ending in REASON_CONNECTIVES:
            return REASON_CONNECTIVES[ending]
        if ending in {'ab', 'ably', 'about', 'not'}:
            return 0.90
    elif head == 'status':
        if ending == 'quo':
            return 1.68
        if ending in {'post', 'epile', 'code'}:
            return 1.12
        if ending in {'text', 'checks', 'information', 'bar', 'report', 'reports'}:
            return 0.75
    elif head == 'state' and ending in {'ful', 'less', 'machine', 'machines'}:
        return 1.0
    elif head == 'purpose' and ending in {'ful', 'fully', 'fulness'}:
        return 1.3
    elif head in {'truth', 'thought', 'meaning'} and ending in {'fully', 'fulness'}:
        return 0.85
    elif head == 'meaning' and ending == 'lessness':
        return 0.82
    elif head == 'method' and ending in {'ological', 'ical', 'ology'}:
        return {'ological': 0.83, 'ical': 0.51, 'ology': 0.33}[ending]
    elif head == 'value' and ending in {
        'added', 'chain', 'chains', 'function', 'proposition'
    }:
        return 0.80
    elif head == 'fact' and ending in {'ually', 'check', 'checking'}:
        return 0.83
    elif head == 'type' and ending in {'check', 'checking', 'ii', 'iii'}:
        return 0.52
    elif head == 'promise' and ending in {'resolve', 'reject', '<void'}:
        return 0.65
    if (head, ending) in STOCK_PHRASES:
        return 0.50
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = older = ''
    if carry is not None and carry[0] == doc:
        previous, older = carry[1:]
    head, ending = piece(previous), piece(token)
    value = BOUNDARIES.get(token, 0.0) + completion(head, ending)
    if token == '-art' and previous == '-the':
        value = 0.49  # state-of-the-art
    if ending == 'why' and previous == ',' and piece(older) in {'reason', 'reasons'}:
        value = 1.38
    return (doc, token, previous), float(value)

programs.haiku:
"""Prepositions and conjunctions that join words inside a camelCase, snake_case or
kebab-case identifier, such as getResultByPost, addContactsToGroup, ToString, _with."""
import re

READS = ()

JOINERS = frozenset(
    "with of to by for from in on and or after before into as at without per between".split()
)
FIRST_WORD = re.compile(r"[A-Z][a-z]*|[a-z]+")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    before = prefix.token_strings[-2][-1:]
    core = token.lstrip("_-./")
    word = FIRST_WORD.match(core)
    if not word or word.group().lower() not in JOINERS:
        return carry, 0.0
    if token[:1] == "_":
        return carry, -2.1
    if token[:1] == "-":
        return carry, -1.0
    if token[:1] == ".":
        return carry, -0.45
    if token[:1].isupper() and (before.islower() or before.isdigit()):
        return carry, -3.0
    return carry, 0.0

programs.sol:
"""A detector dominated by Czech letters with carons, plus PHP syntax.

Isolated e/r with a caron give the largest response; the Czech word
fragment 'př' and less common accented Latin letters give smaller ones.
PHP closing tags and output statements also activate it. Completed
byte-fragment tokens for e/r with carons are recognized too. Most
other text is ignored, except a document-initial heading marker.
"""
import unicodedata

READS = ()


def accented_letter(token):
    if len(token) != 1:
        return 0.0
    name = unicodedata.name(token, '')
    if not name.startswith('LATIN') or ' WITH ' not in name:
        return 0.0
    base, marks = name.split(' WITH ', 1)
    letter = base[-1].lower()
    if marks == 'CARON':
        if letter in 'er':
            return 4.3
        if letter == 'n':
            return 1.5
        if letter in 'dtl':
            return 0.85
        return 0.2
    if letter == 'u' and marks == 'RING ABOVE':
        return 1.0
    if letter == 'e' and marks == 'DOT ABOVE':
        return 1.2
    if marks == 'DOUBLE ACUTE':
        return 0.55 if letter == 'o' else 0.3
    if marks == 'MACRON' and letter in 'eou':
        return 0.45
    if marks == 'ACUTE' and letter in 'cnsz':
        return 0.4
    if letter == 'n' and marks == 'TILDE':
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = (prefix.position == 0 or
                    prefix.document_ids[-1] != prefix.document_ids[-2])
    if new_document and token == '#':
        value = 0.98
    elif token.strip() == 'př':
        value = 1.9
    elif token.lstrip().startswith('?>'):
        value = 4.8 if token.endswith('\n') else 3.8
    elif token.strip() in {'echo', 'fwrite'}:
        value = 1.0
    else:
        # Recover a caron letter if this byte token completes it.
        if token == '\ufffd':
            completed = prefix.text_prefixes[-1][-1:]
            if completed in ('ě', 'ř'):
                token = completed
        value = accented_letter(token)
    return None, value

programs.haiku:
"""Stacked-modifier detector for layers.0.mlp.down_proj component 3481.

Main effect: the component goes negative on an adverb that directly follows another
intensifier or negation, as in "more particularly", "almost entirely", "very slightly",
"not only", "highly likely", "really only". The adverb is the second word of a stacked
modifier. Plain adverbs after verbs, and most other tokens, stay near zero.

Secondary effect: the word right after "more", "most", "very", "really", "almost" or
"quite" is pushed positive if it is a evaluative adjective ("most effective", "very
useful", "most popular"), and negative if it is a specificity adjective ("more general",
"most similar", "more specific", "very particular").

Each token gets one number. The main effect uses the current token being an adverb
(a word ending in -ly, or one of "only", "just", "always", "often", "likely", "enough").
If the previous token (same document) is a strong intensifier, the value is -1.3; a
negation or weak intensifier gives -0.6; a previous -ly adverb gives -0.8.
"""

READS = ()

PLAIN_ADVERBS = {"only", "just", "always", "often", "likely", "enough"}
NOT_ADVERBS = {"family", "early", "daily", "apply", "supply", "assembly", "reply", "holy",
               "italy", "belly", "jelly", "fly", "rely", "july", "friendly", "lovely", "ugly"}
STRONG = {"more", "most", "very", "almost", "quite", "really", "only"}
WEAK = {"not", "n't", "’t", "'t", "too", "never", "less", "also", "so", "than", "just", "even"}
EVALUATIVE = {"good", "useful", "effective", "efficient", "helpful", "popular", "expensive",
              "significant", "interesting", "appealing", "common", "important", "valuable"}
SPECIFIC = {"general", "similar", "specific", "particular", "limited", "certain", "real",
            "complete", "unique", "special"}
DEGREE = {"more", "most", "very", "really", "almost", "quite"}


def is_adverb(word):
    if word in PLAIN_ADVERBS:
        return True
    return word.isalpha() and word.endswith("ly") and len(word) >= 5 and word not in NOT_ADVERBS


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    word = prefix.token_strings[t].strip().lower()
    before = prefix.token_strings[t - 1].strip().lower()
    if is_adverb(word):
        if before in STRONG:
            return None, -1.3
        if before in WEAK:
            return None, -0.6
        if before.isalpha() and before.endswith("ly") and len(before) >= 5:
            return None, -0.8
        return None, 0.0
    if before in DEGREE:
        if word in EVALUATIVE:
            return None, 0.3
        if word in SPECIFIC:
            return None, -0.5
    return None, 0.0

programs.sol:
"""A lexical detector of large quantities, with weaker decimal-pair responses.

Hundreds, thousands, millions and larger scale words receive large positive
values, including Chinese units and a few translated or fragmented forms.
'Few', 'several' and 'many' amplify a scale; 'one' weakens it. Plurals carry
onto the following 'of'. Adjacent 00, 98 and 99 receive smaller responses;
low digits after 9 receive small negative responses. Other digit pairs have
small corrections; unrelated tokens are zero. The approximation keeps the
large quantity spikes rather than memorizing diffuse vocabulary biases.
"""
READS = ()

# Calibrated amplitudes for familiar quantity words and scale-word fragments.
QUANTITY = {
    'hundred': 2.8, 'hundreds': 2.4,
    'thousand': 6.3, 'thousands': 5.6,
    'million': 6.5, 'millions': 6.8,
    'billion': 7.3, 'billions': 8.1, 'trillion': 7.8, 'trillions': 8.0,
    'illion': 6.0, 'illions': 7.6, 'ousand': 5.8, 'ousands': 4.9,
    'undred': 2.3, 'undreds': 2.1,
    'mil': 1.5, 'mill': 0.8, 'millones': 3.7, 'millionen': 5.6,
    'миллион': 4.4, 'млн': 3.6, 'тысяч': 2.8, 'тыся': 3.7,
    'nghìn': 4.2, 'triệu': 4.2, 'milhões': 4.0,
    'crore': 2.1, 'lakh': 1.9, 'dozen': 1.9, 'dozens': 1.1,
    'countless': 2.3, 'infinite': 1.1, 'myriad': 1.3,
    'huge': 0.7, 'unlimited': 0.9, 'mega': 0.9, 'multi': 0.8,
    'nano': 1.1, 'micro': 0.3, 'billionaire': 2.6,
}

# Chinese number scales and compound expressions, not arbitrary token ids.
CJK = {
    '百': 2.4, '千': 6.5, '万': 5.4, '萬': 5.8,
    '亿': 8.2, '億': 7.0, '百万': 9.9, '千万': 9.8,
    '十万': 7.5, '百亿': 9.0, '万亿': 8.5, '千亿': 8.2,
    '亿万': 10.0, '无数': 2.6, '无限': 1.3,
}

# Joining a scale to a unit changes its amplitude. Currency, counting,
# distance and time units are grouped separately.
UNIT_FACTOR = {
    '元': 0.55, '余元': 0.55, '美元': 0.60,
    '人': 0.95, '个': 1.35, '名': 0.95, '吨': 0.95, '余': 0.95,
    '家': 0.8, '辆': 0.62, '平方米': 0.62,
    '人次': 0.8, '台': 0.8, '户': 0.8, '多': 0.8,
    '年': 0.55, '里': 0.72,
}


def magnitude(s):
    if s in CJK:
        return CJK[s]
    # A numeral/quantifier can be fused with its scale into one token.
    modifier = ''
    if len(s) > 1 and s[0] in '一二三四五六七八九数几上近多':
        modifier = s[0]
    core = s[len(modifier):]
    for root in ('百万', '千万', '十万', '百亿', '万亿', '千亿',
                 '亿万', '亿', '億', '万', '萬', '千', '百'):
        if not core.startswith(root):
            continue
        unit = core[len(root):]
        if unit and unit not in UNIT_FACTOR:
            return 0.0
        value = CJK[root] * UNIT_FACTOR.get(unit, 1.0)
        if modifier and root in ('百', '千'):
            if modifier == '一':
                value *= 0.55
            elif root == '百' and modifier in '数几上':
                value *= 1.4
            else:
                value *= 0.85
        if unit == '元' and root == '万':
            value = 2.5
        return value
    return QUANTITY.get(s.lower().lstrip('-'), 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1].strip()
    # Decode a scale character that has just been completed by continuation bytes.
    if '\ufffd' in s:
        tail = prefix.text_prefixes[-1][-len(s):]
        if tail and '\ufffd' not in tail:
            s = tail if magnitude(tail) else tail[-1]
    value = magnitude(s)
    word, previous = s.lower(), old.lower().lstrip('-')
    if word in ('hundred', 'thousand', 'million', 'billion', 'trillion'):
        value += (-0.6 if previous == 'one' else 1.4 if previous == 'few'
                  else 0.8 if previous in ('several', 'many') else 0.0)
        if previous == 'per':
            value -= 1.4
    if s == 'of' and previous in (
            'hundreds', 'thousands', 'millions', 'billions', 'trillions', 'dozens'):
        if previous == 'dozens':
            value = 1.5
        elif old == 'Millions':
            value = 4.9
        else:
            value = 0.93 * magnitude(old)
    if (word in ('ion', 'ions', 'ionen', 'ioni')
            and previous.endswith(('mill', 'bill'))):
        value = 6.0 if word == 'ion' else 6.4
    if len(s) == 1 and s in '0123456789':
        d = int(s)
        if old == '0':
            value = 0.71 if d == 0 else -0.07 if 2 <= d <= 7 else 0.0
        elif old == '9':
            if d < 6:
                value = -0.25 + 0.043 * d
            else:
                value = 0.045 * (d - 6)**2 + 0.085 * (d - 6) + 0.10
        elif old in ('7', '8') and d >= 8:
            value = 0.12 + 0.04 * (d - 8)
        elif old == '5' and d == 0:
            value = 0.13
    return (doc, s), float(value)

programs.luna:
"""Predict activation bumps for long numerals and words of scale.

Long digit strings are a weak cue; magnitude words such as “million” are much
stronger. Most ordinary tokens get a prediction near zero.
"""

READS = ()

LARGE_UNITS = (
    "million", "billion", "trillion", "thousand", "hundred", "千",
)
SCALE_WORDS = (
    "huge", "mega", "unlimited", "everest", "nano", "eternal",
    "slight", "tons", "百",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == doc:
        previous = prefix.token_strings[-2].strip()

    run, kind = "", ""
    if carry is not None and carry[0] == doc:
        run, kind = carry[1], carry[2]

    if token and all(ch.isdigit() or ch in ",._" for ch in token) and any(
        ch.isdigit() for ch in token
    ):
        digits = "".join(ch for ch in token if ch.isdigit())
        run = run + digits if kind in ("number", "separator") else digits
        kind = "separator" if token[-1] in ",._" else "number"
    elif token in {",", ".", "_"} and run:
        kind = "separator"
    else:
        run, kind = "", ""
    carry = (doc, run, kind)

    value = 0.0
    if len(run) >= 3:
        value += 0.043
    if run.startswith(("19", "20")) and 3 <= len(run) <= 4:
        value += 0.083
    if token.isdigit() and previous.isdigit():
        value += 0.019

    word = token.casefold()
    if word.startswith(LARGE_UNITS):
        return carry, 6.625
    if word == "of" and previous.casefold().startswith(LARGE_UNITS):
        return carry, 5.751
    if any(word.startswith(root) for root in SCALE_WORDS):
        value += 0.567
    return carry, value

"""Predict a place-related signal: strongest on place words, weaker on place names in context."""
READS = ()

PLACE_WORDS = frozenset({
    "city", "cities", "town", "towns", "village", "borough", "county", "district",
    "state", "province", "region", "island", "street", "road", "avenue", "suburb",
    "suburbs", "neighborhood", "neighbourhood", "urban", "downtown", "municipality",
    "center", "centre", "station", "airport", "park", "mall", "market", "university",
    "hospital", "school", "house", "garage", "kitchen", "church", "hotel", "museum",
    "square", "campus", "building", "establishment", "establishments", "community",
    "harbor", "harbour",
})
EAST_ASIAN_PLACE_ENDINGS = (
    "市", "区", "區", "县", "縣", "省", "州", "乡", "鄉", "镇", "鎮", "村",
    "県", "府", "都", "町", "島", "道", "郡", "시", "도", "군", "구",
)
PLACE_PREPOSITIONS = frozenset({
    "in", "at", "from", "to", "near", "across", "around", "within", "outside",
    "into", "through", "along", "between", "on", "off", "by", "toward", "towards",
})


def _word(token):
    return token.strip().strip(".,;:!?()[]{}\"'“”‘’<>—–").lower()


def _title(token):
    word = token.strip()
    return bool(word and word[0].isupper() and any(ch.isalpha() for ch in word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    word = _word(token)
    title = _title(token)
    previous = old[-1][0] if old else ""
    place_suffix = word.endswith(EAST_ASIAN_PLACE_ENDINGS)
    near_place = any(w in PLACE_WORDS for w, _ in old[-3:])

    value = 0.008
    if word in PLACE_WORDS:
        value += 0.56
    if place_suffix:
        value += 1.12
    if title and previous in PLACE_PREPOSITIONS:
        value += 0.04
    if title and near_place:
        value += 0.12

    history = (old + ((word, title),))[-4:]
    return (doc, history), float(value)

programs.sol:
"""Recognize value/price spellings, especially the short piece `val`.

Price words and lone price ideographs fire strongly. Value words, spelling
relatives (valley, valve, interval), and evaluation words fire less strongly.
Remember one token for split val+suffix words and for 評+價/価 ('evaluation').
Unrecognized spellings receive zero; finer context-dependent variation is omitted.
"""
import re

READS = ()
# Simplified Chinese, traditional Chinese, and Japanese price/value ideographs.
PRICE_CHARS = {'价': 7.5, '價': 6.5, '価': 5.3}
# Spanish, Turkish, and Russian words for price or cost.
PRICE_WORDS = {'precio', 'precios', 'fiyat', 'цена', 'стоимость', 'стоимости'}
VAL_ENDINGS = {'ence', 'ency', 'ent', 'ently', 'ued', 'uing', 'uable',
               'uation', 'uations', 've', 'ves', 'ved', 'ley', 'leys'}


def lexical_value(token):
    raw = token.strip()
    word = raw.strip('_-.,:;()[]{}<>"\'').lower()
    if raw in PRICE_CHARS:
        return PRICE_CHARS[raw]
