        return 0.8
    if word == 'val':
        return 2.5 if raw.startswith(('_', '(')) or raw.isupper() else 3.3
    if 'price' in word or word == 'pricing':
        return 1.5 if word.endswith(('priced', 'pricey', 'priceless')) else 2.7
    if 'valuable' in word or word == 'valued':
        return 1.9
    if word.startswith('valuat'):
        return 2.5
    if 'value' in word:
        return 1.15
    if word.startswith('valid'):
        return 0.5 if 'ation' in word else 0.15
    if word.startswith('eval'):
        return 0.85
    if 'interval' in word or word.startswith('val'):
        return 1.3
    if re.fullmatch(r'[a-z]{1,2}vals?(?:ent)?', word):
        return 0.6 if token[:1].isspace() else 1.9
    if word in {'va', 'ava', 'eva', 'iva'}:
        return 0.5
    if word in {'expensive', 'inexpensive', 'bargain'}:
        return 1.0
    if word.startswith('cheap') or word == 'costly':
        return 0.65
    # Vietnamese, Russian, and Thai words for price(s).
    if word in {'giá', 'цены', 'ราคา'}:
        return 2.2
    if word in PRICE_WORDS:
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = lexical_value(token)
