    if "pricing" in word:
        return None, 2.1
    if word == "price":
        return None, 3.1
    if "price" in word:
        return None, 2.6
    if any(term in word for term in ("低价", "价格", "价", "價", "цены", "цен", "金额", "缴费")):
        return None, 2.5
    if any(term in word for term in ("cheap", "expensive", "pricey")):
        return None, 0.9
    if "value" in word:
