programs.sol:
"""Detect right-pointing arrows, with smaller responses to indentation.

Thin arrows (-> and →) have the largest response. Parentheses, self references,
extra hyphens and attached text weaken it; whitespace changes its strength.
Also recognize fat/left arrows and the LaTeX name rightarrow. Short runs of
spaces following a tab have a separate, weaker response. Everything else is
zero. Only the previous token is remembered, resetting between documents.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = token.strip()
    spaced = token[:1].isspace()
    value = 0.0

    if '->' in text:
        before, after = text.split('->', 1)
        if before.endswith('-'):
            value = 2.2 if spaced else 3.0
        else:
            left = before or previous.rstrip()
            value = 6.25 if spaced else 6.0
            if left.endswith((')', ']')):
                value = 4.75 if before else 5.05
            elif left.strip().lstrip('$') in ('this', 'self'):
                value = 4.6
            elif not left:
                value = 5.2
            elif not left[-1].isalnum() and left[-1] != '_':
                value = 5.6
            if after:
                value = 2.5
        if '\n' in token:
            value *= 0.45
    elif '→' in text:
        value = 2.5 if spaced else 2.95
        if previous.rstrip().endswith((')', ']')):
            value -= 0.4
        if '\n' in token:
            value *= 0.4
    elif '=>' in text:
        value = 0.91 if spaced else 1.26
        if text.startswith('==') and spaced:
            value = 0.42
        if '\n' in token:
            value = 0.62
    elif text == 'rightarrow':
        value = 1.4
    elif text == 'longrightarrow':
        value = 0.33
    elif text == '<-':
        value = 0.95
    elif token.startswith('\t') and token[1:] and set(token[1:]) == {' '}:
        spaces = len(token) - 1
        if spaces < 3:
            value = 0.11 + 0.11 * spaces
        else:
            value = max(-0.08, 0.69 - 0.07 * (spaces - 3)
                        - 0.045 * max(0, spaces - 7))

    return (doc, token), float(value)

programs.luna:
"""Recognize arrow-like relation markers, which are this component's strongest trigger."""

READS = ()


def step(carry, prefix, upstream):
    """Give relation arrows a positive pulse; ignore other tokens."""
    token = prefix.token_strings[-1].rstrip()

    if token.endswith("-->"):
        return None, 2.2
    if token.endswith("->"):
        return None, 5.5
    if token.endswith("→"):
        return None, 2.6
    if token.endswith("=>"):
        return None, 1.0
    return None, 0.0

programs.sol:
"""A lexical detector for errors, warnings, and diagnostic-message openings.

Error names and invalid/missing-value words get negative scores, stronger in
code or capitalized diagnostics than in prose. Colons and quotes are scored
as message openings when they follow diagnostic labels or error constructors.
Escaped quotes have a weaker score. Local failure phrases such as
"failed to", "could not", and "invalid argument" also matter.
A few negated constructions get small positive scores. This uses
only two preceding tokens, resets at document boundaries, and otherwise
predicts zero; it does not attempt to reproduce arbitrary token-specific noise.
"""
from functools import lru_cache

READS = ()

# Lowercase prose, lowercase code, title case, uppercase diagnostic label.
DIAGNOSTICS = {
    'error': (-0.98, -1.8, -2.5, -1.7),
    'errors': (-0.23, -0.8, -0.8, -0.9),
    'warning': (-2.45, -2.3, -3.2, -2.3),
    'warnings': (-1.7, -1.7, -1.7, -1.7),
    'warn': (-0.9, -1.1, -1.1, -1.1),
    'invalid': (-1.7, -2.9, -3.4, -2.4),
    'undefined': (-1.6, -1.4, -2.2, -1.8),
    'malformed': (-3.2, -3.2, -3.5, -3.0),
    'unexpected': (-2.2, -3.1, -3.5, -2.5),
    'missing': (-0.86, -1.75, -1.6, -1.6),
    'failed': (-0.87, -2.1, -2.5, -0.9),
    'cannot': (-0.25, -0.6, -2.6, -1.0),
    'could': (-0.09, -0.8, -1.1, -0.5),
    'no': (-0.09, -0.26, -0.4, -0.25),
    'not': (-0.06, -0.45, -0.6, -0.25),
    'expected': (-0.35, -0.75, -1.25, -1.3),
    'illegal': (-1.05, -2.4, -3.1, -2.2),
    'unknown': (-0.44, -1.4, -1.5, -2.3),
    'unsupported': (-1.9, -2.8, -3.0, -2.5),
    'unrecognized': (-2.0, -2.5, -2.7, -2.5),
    'internal': (-0.33, -1.1, -0.7, -1.1),
    'fatal': (-1.4, -1.5, -1.8, -1.8),
    'wrong': (-0.56, -2.0, -1.2, -1.5),
    'bad': (-0.49, -0.8, -0.7, -1.0),
    'deprecated': (-0.87, -1.2, -1.95, -1.8),
    'exception': (-0.22, -0.9, -1.3, -1.3),
    'exceptions': (-0.2, -1.0, -1.0, -1.0),
    'unable': (-0.65, -2.5, -2.4, -2.4),
    'mismatch': (-1.1, -1.9, -2.3, -2.3),
    'incompatible': (-1.3, -2.0, -2.0, -2.0),
    'incorrect': (-0.5, -2.2, -2.3, -2.3),
    'duplicate': (-0.6, -1.0, -1.0, -1.0),
    'unresolved': (-0.6, -1.3, -1.6, -1.6),
}


@lru_cache(maxsize=8192)
def diagnostic(token):
    word = token.strip().lstrip('._-/>(\\')
    lower = word.lower()
    spaced = token[:1].isspace()
    if word in {'TypeError', 'ValueError'}:
        return word, -4.2
    if word.endswith('Error') and len(word) > 5:
        if word == 'NoError' or word[:1].islower():
            return lower, -2.8 if word == 'fatalError' else 0.0
        return word, -2.5 if word == 'AssertionError' else -3.0
    if word.endswith('Exception') and len(word) > 9:
        if word in {'IOException', 'SQLException'}:
            return word, 0.0 if spaced else -1.0
        return word, -3.7 if 'Illegal' in word or 'Invalid' in word else -2.4
    if lower in DIAGNOSTICS:
        variant = (3 if word.isupper() else 2 if word[0].isupper()
                   else 0 if spaced else 1)
        value = DIAGNOSTICS[lower][variant]
        if token in {'.Error', '_Error'}:
            value = -0.35
        elif word in {'Error', 'Exception'} and spaced:
            value = -1.95 if word == 'Error' else -0.16
        return lower, value
    if lower in {'errorf', 'fatalf', 'perror'}:
        return lower, -1.1
    if lower == 'err':
        value = -0.12 if word == 'err' else -0.8 if word == 'Err' else -1.6
        return lower, value
    if word in {'NotFound', 'NotAllowed', 'NoSuch', 'BadRequest'}:
        return lower, -2.5
    if lower in {'❌', '⚠', '警告', 'erreur', '错误'}:
        return 'warning', -1.3
    return lower, 0.0


# Message labels fall into familiar diagnostic classes.
LABEL_GROUPS = (
    ({'error', 'err'}, -3.3),
    ({'deprecated'}, -4.4),
    ({'exception', 'fatal', 'failure'}, -2.8),
    ({'failed', 'fail'}, -1.6),
    ({'unexpected', 'expected', 'invalid', 'undefined'}, -1.15),
    ({'note', 'hint', 'debug', 'info', 're'}, -1.25),
    ({'usage', 'notice'}, -1.9),
    ({'message', 'pass', 'success'}, -0.7),
)
ERROR_MODIFIERS = {'syntax', 'parse', 'parsed', 'runtime', 'value', 'type',
                   'import', 'fatal', 'server', 'cuda', 'internal'}
NEGATION = {'not', 'no', 'cannot', "'t", '’t'}
SOURCE_SUFFIXES = {'java', 'py', 'go', 'js', 'ts', 'rs', 'c', 'cpp', 'h'}


def colon(previous, word):
    if word == 'warning':
        return -5.0 if previous.strip() == 'Warning' else -3.0
    if word in {'TypeError', 'ValueError'}:
        return -5.1
    if word.endswith(('Error', 'Exception')):
        return -3.8
    if previous.startswith('.') and word in SOURCE_SUFFIXES:
        return -0.75
    if previous.strip().isdigit():
        return -0.15
    for words, value in LABEL_GROUPS:
        if word in words:
            return value
    return -0.03


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before, severity = '', '', 0.0
    else:
        _, previous, before, severity = carry
    word, value = diagnostic(token)
    old_word, _ = diagnostic(previous)

    if word in {'error', 'errors'} and old_word in ERROR_MODIFIERS:
        value -= 2.7 if token.startswith(' ') else 1.4
    elif word in {'error', 'errors'} and old_word == 'the':
        value *= 0.3
    elif word in DIAGNOSTICS and previous == ':':
        value -= 0.7
    lexical_severity = value

    if token in {':', '：'}:
        value = colon(previous, old_word)
    elif token in {'("', "('", '(\\"'}:
        if old_word.endswith(('Error', 'Exception')):
            value = -2.25
        elif old_word in {'errorf', 'fatalf', 'perror', 'fatal', 'fatalerror'}:
            value = -2.0
        elif old_word in {'error', 'warn', 'warning', 'exception', 'err'}:
            value = -1.7
        elif old_word in {'printf', 'println'}:
            value = -0.65
        else:
            value = -0.04
        if '\\' in token:
            value *= 0.3  # Escaped message openings have a weaker response.
    elif token in {' "', " '"}:
        value = -0.27 if previous.endswith(':') else -0.03
        if previous == ':' and diagnostic(before)[0].endswith(('Error', 'Exception')):
            value = -1.6
    elif token == ' to' and old_word in {'failed', 'unable', 'fatal'}:
        value = 1.3 * severity
    elif word == 'not' and old_word == 'could':
        value = -2.3 if before == ':' else -0.75 if previous == ' could' else -2.7
    elif word in {'argument', 'arguments', 'token', 'occurred'} and severity < -0.6:
        value += 0.8 * severity
    elif token == '!':
        value = 0.55 * severity

    if token == ' of' and old_word in {'error', 'errors', 'exception'}:
        value = 1.0
    elif token == ' be' and old_word in NEGATION:
        value = 0.35
    elif word in {'necessarily', 'clear'} and old_word in NEGATION:
        value = 0.85
    elif word in {'catch', 'throws', 'fail', 'anything'} or token in {' !=', '≠'}:
        value = 0.32
    return (doc, token, previous, lexical_severity), float(value)

programs.haiku:
"""Error-report neuron (layer 0, MLP channel 3487).

Negative on words that announce an error or warning ("Error", "Invalid", "warning",
"Unexpected", "Cannot", "*Error" class names), less negative on words that report a
failure or a missing thing ("failed", "missing", "undefined", "expected"), and most
negative on a colon right after an error word ("Error:", "warning:"). Zero elsewhere.
"""
import re

READS = ()

ERROR_WORDS = {"error", "errors", "err", "invalid", "warning", "warnings", "unexpected",
               "unsupported", "unknown", "cannot", "fatal"}
FAILURE_WORDS = {"failed", "fail", "missing", "undefined", "expected", "wrong",
                 "exception", "exceptions"}

def _word(token):
    return token.strip().lower()

def _tier(token):
    """2 for an error word, 1 for a failure word, 0 otherwise."""
    w = _word(token)
    if w in ERROR_WORDS or re.search(r"(error|exception|warning)$", w):
        return 2
    if w in FAILURE_WORDS:
        return 1
    return 0

VALUE = {2: -1.25, 1: -0.7}          # activation on the word itself
COLON_AFTER = {2: -2.6, 1: -1.0}     # activation on a colon right after such a word

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if toks[-1].strip() == ":" and len(toks) > 1 and _tier(toks[-2]) > 0:
        return None, COLON_AFTER[_tier(toks[-2])]
    return None, VALUE.get(_tier(toks[-1]), 0.0)

programs.luna:
"""Flag terse error reports: exception names, failed checks, and missing values.

The component's larger negative responses in harvested text cluster around
diagnostics. This small predictor looks for those words, plus the colon after
an exception label; it leaves other text at zero.
"""

READS = ()

STRONG_ERRORS = (
    "error", "exception", "traceback", "undefined", "missing", "failed",
    "failure", "warning", "illegal", "invalid",
)
OTHER_PROBLEMS = (
    "expected", "duplicate", "unable", "cannot", "issue", "problem",
)


def _has(text, words):
    return any(word in text for word in words)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ()
    else:
        tail = carry[1]

    current = prefix.token_strings[-1].lower()
    value = 0.0
    if _has(current, STRONG_ERRORS):
        value = -1.5
    elif _has(current, OTHER_PROBLEMS):
        value = -0.7

    previous = tail[-1].lower() if tail else ""
    if ":" in current and _has(previous, STRONG_ERRORS):
        value = -2.0
    elif previous.strip().lower() in {"failed", "failure"} and "to" in current:
        value = -1.4

    new_tail = (tail + (prefix.token_strings[-1],))[-6:]
    return (doc, new_tail), float(value)

programs.sol:
"""A closing-brace detector, strongest at the end of a code block.

A brace on an otherwise blank or numbered line responds strongly; inline
braces respond less. LaTeX groups and empty braces are weaker still.
Attached newlines, parentheses, commas, semicolons, and quotes adjust the
response. Comment endings, empty square brackets, book-title brackets,
and a few conversation delimiters receive small positive responses.
Only the last 256 characters are carried, resetting between documents.
"""
import re

READS = ()
LATEX = re.compile(
    r'\\(?:frac|sqrt|text|math[a-z]*|begin|end|left|right|vec|overline|'
    r'prod|sum|lim|alpha|beta|gamma|lambda|theta|eta|pi)\b'
)
ENVIRONMENT = re.compile(r'\\(?:begin|end)\{[^{}]*$')
GUTTER = re.compile(
    r'\s*(?:\d+\s+)?(?:[+\-*]|//|/\*\s*\d*\s*\*/)?[\s`]*'
)


def closing_brace(s, before):
    body = s.strip()
    newline = '\n' in s or '\r' in s
    spaced = s.startswith((' ', '\t'))
    if '{}' in body:
        return 0.8
    if ENVIRONMENT.search(before):
        return -0.1 if newline else 0.05
    if body.startswith(('}{', '}_', '}(', '}=')):
        return 0.05
    if body.startswith('},{'):
        return 0.65
    if body.startswith('}$'):
        return 0.25
    if LATEX.search(before):
        return -0.1 if body.startswith('})') else (0.3 if newline else 0.4)
    if body.startswith(('"}', "'}")):
        return 1.9 if '}}' in body and newline else 1.4
    if body.startswith('}}'):
        return 2.0 if newline else 1.2
    if not body.startswith('}'):
        return 3.3 if body.startswith(';}') else 1.4

    logical = before.replace('\\n', '\n').replace('\\r', '\n')
    logical = logical.replace('\\t', '\t')
    line = logical.rsplit('\n', 1)[-1]
    own_line = bool(GUTTER.fullmatch(line))
    own_line |= bool(re.search(r'`[ \t\u00a0]+`*$', line))
    tail = body[1:]
    if tail.startswith(('while', '//', '*/')):
        return 3.3 if newline else 4.2
    if tail.startswith('\\'):
        return (3.2 if spaced else 2.6) if own_line else 1.45
    if tail.startswith(')'):
        if tail.startswith('))'):
            return 1.0
        return 1.95 if newline or ';' in tail else (1.4 if spaced else 0.65)
    if tail.startswith(';'):
        return (3.0 if own_line else 1.7) if newline else 1.5
    if tail.startswith(','):
        if spaced:
            return 2.65 if newline else 2.3
        return 2.4 if own_line or newline else 1.1
    if tail:
        return 3.0 if tail.startswith('`') and own_line else 0.6
    if not own_line:
        return 1.6 if newline else (2.4 if spaced else 0.8)
    if not before:
        return 3.1 if newline else 2.12
    if '\\n' in before[-40:] or '\\t' in before[-40:]:
        return 3.0 if newline else 3.1
    if newline:
        n = s.count('\n')
        return 2.7 if n > 2 else (3.2 if n > 1 else (3.5 if spaced else 3.3))
    return 4.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    if '}' in s:
        value = closing_brace(s, before)
    elif s.strip() in {'《', '》'}:
        value = 0.75
    elif '*/' in s:
        value = 0.5 if '\n' in s else 0.3
    elif s.strip() == '[]':
        value = 0.3
    elif s in {'</tool_call>', '</think>', '<tool_response>'}:
        value = 0.2
    else:
        value = 0.0
    return (doc, (before + s)[-256:]), float(value)

