"""Recognize a closing curly brace, especially at the end of a code line.

The component's strongest responses occur on source-code closing braces. A
line break after the brace is a particularly strong cue; other braces get a
smaller response because they can also be mathematical or textual notation.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    close = token.rfind("}")
    if close < 0:
        return None, 0.0

    before = token[:close]
    after = token[close + 1:]
    if before.endswith("{"):
        value = 0.8
    elif after.startswith("\n"):
        if before.strip() == "":
            value = 3.5
        elif token.count("}") > 1 or '"' in before:
            value = 2.0
        else:
            value = 3.0
    elif after.startswith("\\"):
        value = 1.4
    elif after.startswith(");"):
        value = 2.0
    elif after.startswith((";", ",")):
        value = 2.3
    elif not after or after.isspace():
        if before.endswith((" ", "\t")):
            value = 2.2
        elif before.endswith((")", "(")):
            value = 0.5
        elif token.count("}") > 1:
            value = 0.9
        else:
            value = 0.7
    else:
        value = 0.6
    return None, value

