    capitalized = previous.strip()[:1].isupper()
    value = 0.0
    if not previous and word.lower() == 'given':
        value = -1.88 if word[:1].isupper() else -1.0
    elif before == 'given':
        value = GIVEN_RESPONSE.get(word, 0.0)
        if capitalized:
            if word in {'that', 'the'}:
                value -= 0.65
            elif word in {'this', 'these', 'their', 'your', 'our', 'my'}:
                value -= 0.4
            elif word in {'a', 'an'}:
                value -= 0.12
        if previous.strip().isupper():
            value *= 0.4
    elif before in {'consider', 'considers', 'considered', 'considering'}:
        participle = before == 'considering'
        if word == 'that':
            value = -1.8 if participle else -1.25
        elif word == 'the':
            value = -0.6 if participle else -0.3
        if capitalized and value:
            value -= 0.3 if participle else 0.1
    elif word == 'that':
        value = THAT_RESPONSE.get(before, 0.0)
    elif token == '__(' and before == 'init':
        value = 0.68
    return (doc, token), float(value)

programs.haiku:
"""A clause opener after a word of knowing, noting or 'given' is pushed negative.

The component reads "that" (or "the") right after a word that introduces a fact, a
condition or an assumption. It is most negative after "given" ("given that", "given the"),
then after verbs of acknowledging and knowing ("consider that", "know that", "the fact
that", "note that", "aware that", "provided that"), weaker after opinion and report verbs
("think that", "said that"). It is near zero after "show", "suggest", "is", and on
relative "that" ("characteristics that"). Everything else is 0.
"""

READS = ()

GIVEN = {"given"}
ACKNOWLEDGE = {"consider", "considering", "acknowledge", "acknowledges", "acknowledged",
               "acknowledging", "knowing", "accept", "recognize", "recognizing"}
KNOWLEDGE = {"fact", "recall", "remember", "known", "know", "knew", "knows", "note",
             "noting", "noted", "understand", "understood", "realize", "assuming", "aware",
             "informed", "provided", "except", "mention"}
OPINION = {"think", "suppose", "assume", "find", "such", "stated", "states", "say",
           "said", "believe"}

# Strength of the negative activation for each kind of head word.
STRENGTH = {"given": 3.5, "ack": 1.2, "know": 0.7, "opinion": 0.25}
# The clause opener, or the article after "given", and how much it carries.
OPENERS = {" that": 1.0, " the": 0.7, " their": 0.5}


def head_strength(head):
    if head in GIVEN:
        return STRENGTH["given"]
    if head in ACKNOWLEDGE:
        return STRENGTH["ack"]
    if head in KNOWLEDGE:
        return STRENGTH["know"]
    if head in OPINION:
        return STRENGTH["opinion"]
    return 0.0


def step(carry, prefix, upstream):
    words = prefix.token_strings
    if len(words) < 2:
        return carry, 0.0
    head = words[-2].strip().lower()
    return carry, -head_strength(head) * OPENERS.get(words[-1], 0.0)

