    "understand", "understood", "provided", "noting", "knowing", "accept",
    "realize",
})
OTHER_CLAUSE_HEADS = frozenset({
    "think", "thinks", "believe", "assume", "suppose", "find", "found", "state",
    "states", "stated", "say", "said", "indicate", "indicated", "mention",
    "mentions", "such", "except", "assuming", "explains", "determines",
})


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[-1].strip().lower()
    start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    previous = "" if start else prefix.token_strings[-2].strip().lower()

    if word == "that":
        if previous == ",":
            return None, 0.09
        if previous == "given":
            return None, -3.7
        if previous == "consider":
            return None, -1.3
        if previous in STRONG_CLAUSE_HEADS:
            return None, -0.65
        if previous in OTHER_CLAUSE_HEADS:
            return None, -0.30
    if previous == "given" and word in {"the", "this"}:
        return None, -2.6 if word == "the" else -1.0
    if start and word == "the":
        return None, -0.21
    if start and word == "they":
        return None, -0.33
    if start and word == "we":
        return None, -0.72
    if previous == "the" and word == "given":
        return None, -0.28
    if previous == "the" and word == "fact":
        return None, -0.19
    if word == "the" and previous == "consider":
        return None, -0.33
    if word == "the" and previous == "considering":
        return None, -0.65
    if previous == "at" and word == "the":
        return None, 0.058
    if previous == "which" and word == "is":
