programs.sol:
"""Spelling-based detector for science and academic subjects/departments.

科 ('science/discipline') is strongest, followed by science words and
related academic vocabulary. Korean 과/와 respond even as conjunctions:
this is lexical, not semantic disambiguation. Case and leading spaces
calibrate English science words. Split scientific suffixes and a small
'of'/'to' echo use the preceding token, resetting at document boundaries.
Other tokens receive a near-zero prediction.
"""
READS = ()

# CJK discipline names, course types, medical branches and science compounds.
CJK_GROUPS = (
    (-6.3, {'科'}),
    (-4.7, {'学科', '理科'}),  # Academic disciplines, science subjects.
    (-3.3, {'本科', '专科', '科目', '科室'}),  # Course types, departments.
    (-3.0, {'科学', '科學'}),  # Science, simplified/traditional spelling.
    (-2.7, {'外科', '内科', '妇科', '眼科', '儿科', '社科'}),
    (-1.75, {'科技', '科研', '科创', '科创板', '科教'}),
    (-1.35, {'科幻', '百科', '科学家'}),
    (-1.9, {'社会科学', '中科院'}),
    (-0.7, {'专业', '專業', '专业的', '课', '課', '课程', '課程',
            '学术', '部门', '研究所', '讲课'}),
)
# Subjects, specialties, educational materials, fields and academic institutions.
ACADEMIC_GROUPS = (
    (-0.85, {'subject', 'subjects'}),
    (-0.95, {'specialty', 'disciplines'}),
    (-0.65, {'dept', 'discipline', 'discipl'}),
    (-0.73, {'textbook', 'textbooks', 'undergraduate', 'curriculum',
             'humanities', 'stem', 'specialists', 'interdisciplinary'}),
    (-0.6, {'biology', 'neuroscience'}),
    (-0.35, {'physics', 'chemistry', 'psychology'}),
    (-0.2, {'academic', 'academia', 'medicine'}),
    (-0.14, {'course', 'courses'}),
    (-0.44, {'.edu', 'wikipedia'}),
)


def lexical(token, previous):
    s, w = token.strip(), token.strip().lower()
    for value, words in CJK_GROUPS:
        if s in words:
            return value
    if s.startswith('科学') or s == '自然科学':
        return -2.4
    if '科技' in s or s.startswith('科研'):
        return -0.8
    if s in {'과', '과학', '와'}:
        return -1.22 if s == '와' else -2.6
    if w in {'science', 'sciences'}:
        if not token.startswith(' '):
            return -1.2 if s.islower() else -2.1
        if s.islower():
            return -2.25 if w == 'science' else -1.95
        return -1.94 if w == 'science' else -1.53
    if w in {'scientific', 'scientifically'}:
        return -1.57 if s.islower() else -1.9
    if w in {'scientist', 'scientists'}:
        return -1.1 if w.endswith('s') else -0.9
    if w in {'sci', 'scient', 'scipy'}:
        return -1.25 if token.startswith(' ') else -0.65
    if w in {'ific', 'ifically', 'ist', 'ists'}:
        if previous.lower().endswith('scient'):
            return -1.25 if w.startswith('ific') else -0.8
    if w in {'ience', 'iences'} and previous.lower().endswith('sc'):
        return -1.2
    if w.startswith(('наук', 'науч', 'científ',
                     'wissenschaft', 'issenschaft')):
        return -1.2
    if w in {'العلم', 'علم'}:
        return -0.9
    if w.startswith(('школь', 'курс')):
        return -0.72
    if w in {'department', 'departments'}:
        return -0.92 if s.islower() else -0.66
    if w == 'academy':
        return -0.59 if s[0].isupper() else -0.1
    for value, words in ACADEMIC_GROUPS:
        if w in words:
            return value
    return -0.002


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        _, previous, strength = carry
    raw = lexical(token, previous)
    value = raw
    if strength < -0.5 and token in {' of', ' to'}:
        value = 0.28 * strength if token == ' of' else -0.13
    return (doc, token, raw), float(value)

programs.luna:
"""A word-level approximation to a sparse science-and-academia feature.

Science and scientist terms get a larger negative prediction; selected Chinese
science words, East Asian surgery terms, departments, subjects, and other
academic words get negative predictions too. Other words get zero.
"""
READS = ()

STRONG_WORDS = {
    "science", "sciences", "scientist", "scientists", "scientific",
    "scientifically", "科研", "科学", "科學", "科技", "科技创新",
    "科技創新", "科学技术", "科學技術", "科研技术人员", "科研技術人員",
}
ACADEMIC_WORDS = {
    "department", "departments", "dept", "depts", "subject", "subjects",
    "academy", "academies", "textbook", "textbooks", "medicine",
    "specialty", "专业", "專業", "学术", "學術", "教育部", "研究所",
    "研究院", "课题", "課題", "教科书", "教科書", "undergraduate",
    "undergraduates",
}
CHINESE_SCIENCE = ("科研", "科学", "科學", "科技")
EAST_ASIAN_SURGERY = ("外科", "手術")


def word_value(word):
    if word in STRONG_WORDS:
        return -2.0
    if word.startswith("sci"):
        return -1.0
    if word.startswith("науч"):
        return -1.0
    if "wissenschaft" in word:
        return -1.4
    if word == "mathematical":
        return -0.9
    if word == "mathematics":
        return -0.35
    if word in ACADEMIC_WORDS:
        if word in {"subject", "subjects"}:
            return -0.75
        return -0.55
    return 0.0


def step(carry, prefix, upstream):
    doc, word = carry if carry is not None else (None, "")
    current_doc = prefix.document_ids[-1]
    if doc != current_doc:
        word = ""

    # Reassemble the newest word across BPE pieces; score only words touched
    # by this token, not old text still in the carry.
    touched = False
    candidates = []
    for char in prefix.token_strings[-1].lower():
        if char.isalpha() or char.isdigit():
            word = (word + char)[-48:]
            touched = True
        else:
            if touched and word:
                candidates.append(word)
            word = ""
            touched = False
    if touched and word:
        candidates.append(word)

    value = 0.0
    for candidate in candidates:
        value = min(value, word_value(candidate))
    # Chinese terms often run together without spaces, so inspect only this
    # token for those cues instead of letting a past word trigger repeatedly.
    piece = prefix.token_strings[-1]
    if any(term in piece for term in CHINESE_SCIENCE):
        value = min(value, -2.0)
    elif any(term in piece for term in EAST_ASIAN_SURGERY):
        value = min(value, -1.0)
    elif any(term in piece or word.endswith(term) for term in (
        "专业", "專業", "学术", "學術", "教育部", "研究所", "研究院",
        "课题", "課題", "教科书", "教科書", "科目", "中科院",
    )):
        value = min(value, -0.55)
    elif word.endswith("教科"):
        value = min(value, -0.55)
    return (current_doc, word), value

programs.sol:
"""A negative signal for dependency declarations near the beginning of code.

Bare import/include/from/using keywords are strongest. Recent declarations
reinforce the signal; prose and quoted code weaken it. Import line endings,
header suffixes, and related declaration words get smaller negative values.
Only the last 1200 characters are retained, reset at each document boundary.
"""
import re

READS = ()


def activation(s, history, position):
    line = history.rsplit('\n', 1)[-1]
    start = not line.strip()
    escaped = not history.rsplit('\\n', 1)[-1].strip()
    java = bool(re.search(
        r'(?:import|package) (?:java|javax|com|org|android|lombok|net)\b',
        history))
    python = bool(re.search(r'(?:^|\n|\\n)(?:import |from )', history))
    csharp = bool(re.search(r'using [A-Z]', history))
    cpp = '#include' in history
    snippet = '```' in history or '<|im_start|>' in history
    factor = 0.65 if snippet else 1.0
    word = s.strip()
    value = 0.0

    if s == '#include':
        value = -4.5 if position == 0 else (-6.1 if cpp else -4.0)
        return value * factor
    if word in {'import', 'from', 'using', 'use', 'package', 'namespace'}:
        bare = s == word
        if word == 'import':
            if bare:
                if position == 0:
                    value = -4.06
                elif start:
                    value = -5.0 if java else (-3.0 if python else -2.6)
                elif escaped:
                    value = -2.2 if java else (-0.92 if python else -0.5)
                else:
                    value = -0.45
            else:
                value = -1.0 if java and s.startswith('\t') else -0.4
                if start:
                    value = -1.3
        elif word == 'from':
            if bare:
                if position == 0:
                    value = -4.65
                elif start:
                    value = -5.2 if python else -1.95
                elif escaped:
                    value = -2.8 if python else -1.2
                else:
                    value = -0.35
            elif start or s.startswith('\t'):
                value = -2.1
            elif re.search(r'\b(?:import|export)\b', line):
                value = -3.2
            else:
                value = -0.02
        elif word == 'using':
            if bare and (start or position == 0):
                value = -6.9 if csharp else -3.8
            else:
                value = -0.2 if bare else 0.0
        elif word == 'use':
            value = -0.35 if bare else -0.03
            if bare and (start or escaped):
                value = -5.5 if '<?php' in history else -2.6
            if s.startswith('\t'):
                value = -1.4
        elif word == 'package':
            value = -2.37 if bare and (start or position == 0) else -0.15
        elif word == 'namespace':
            value = -2.4 if bare and start else (-0.6 if cpp else -0.1)
        return value * factor

    # Small responses to the rest of a dependency declaration.
    dependency_line = bool(re.match(
        r'\s*(?:import|from|using|use|package|#include)\b', line))
    if '\n' in s:
        if dependency_line:
            if ';' in s:
                value = -1.25 if java or csharp else -0.65
                if s.count('\n') > 1:
                    value -= 0.25
            else:
                value = -0.55
        elif ';' in s:
            value = -0.18 - 0.12 * min(2, s.count('\n') - 1)
        elif '*/' in s:
            value = -0.25
        elif '"' in s or "'" in s:
            value = -0.2
        return value * factor
    if s in {'.h', '.hpp'}:
        return -1.1
    if word in {'private', 'extern', 'typedef'}:
        return -0.6
    if s in {'public', 'const', 'export'}:
        return -0.45
    if word in {'extends', 'require'}:
        return -0.5
    if (s.startswith('#') and word[1:] in
            {'define', 'ifndef', 'ifdef', 'pragma', 'endif'}):
        return -1.4 if word in {'#ifndef', '#pragma'} else -0.8
    if word in {'License', 'Copyright', 'LICENSE'}:
        return -0.5
    if word in {'org', 'com', 'github'} or s in {'.util', '/org', '/licenses'}:
        return -0.4
    if s in {'.from', '_from', 'From', '.From'}:
        return -0.55
    if s == 'include' and history.endswith('#'):
        return -2.0
    if s == "'use":
        return -4.9
    return value


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        history, position = '', 0
    else:
        _, history, position = carry
    s = prefix.token_strings[-1]
    value = activation(s, history, position)
    return (doc, (history + s)[-1200:], position + 1), float(value)

programs.luna:
"""Recognize common source-code declarations, import words and syntax
boundaries. 'From' and 'use' also receive weak predictions in ordinary text;
recent code cues make imports and related words stronger.
"""
READS = ()

WORDS = {
    "import": -0.7,
    "from": -0.65,
    "namespace": -1.5,
    "package": -0.8,
    "class": -0.45,
    "public": -0.9,
    "extends": -0.9,
    "private": -0.6,
    "typedef": -0.7,
    "using": -0.45,
    "use": -0.5,
    "uses": -0.5,
}
CODE_WORDS = {
    "import": -2.5,
    "from": -2.6,
    "using": -2.2,
}
CODE_CUES = (
    "import ", "namespace ", "package ", "class ", "public ",
    "private ", "typedef ", "#include", "#endif", ";\n", "{\n",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = "" if carry is None or carry[1] != doc else carry[0]
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.casefold().strip("._")
    code = any(cue in history.casefold() for cue in CODE_CUES)

    if word in WORDS:
        value = CODE_WORDS.get(word, WORDS[word]) if code else WORDS[word]
    elif word in CODE_WORDS and code:
        value = CODE_WORDS[word]
    elif raw.casefold() == "'use":
        value = -3.5
    elif word == "strict" and "'use" in history.casefold():
        value = -0.6
    elif raw.startswith("#include"):
        value = -2.2
    elif raw.startswith("#endif"):
        value = -0.5
    elif raw.startswith(("//", "/**", "*/")):
        value = -0.8
    elif raw.startswith(";") and "\n" in raw:
        value = -0.8
    elif raw.startswith("};"):
        value = -0.55
    elif "\n\n\n" in raw:
        value = -0.5
    else:
        value = 0.0

    history = (history + token)[-180:]
    return (history, doc), value

programs.haiku:
"""Layer-0 MLP down_proj component 3493: a weak, mostly token-driven feature.

Its activation is small (RMS 0.035) and sign-mixed. Almost all of it is
not explained by any short concept; the few things that are stable here:

* the reasoning tag token "<think>" pushes it negative (about -0.2);
* Chinese administrative-division characters (省, 县, 縣, 市) push it negative (about -0.15);
* the first token of a document sits slightly negative (about -0.01).

Everything else is predicted as 0. Carries no state beyond the document start.
"""

READS = ()

THINK_TAG = "<think>"
ADMIN_CHARS = set("省县縣市")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == THINK_TAG:
        return carry, -0.2
    if token.strip() in ADMIN_CHARS:
        return carry, -0.15
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.01
    return carry, 0.0

