QUALITY = {'correct', 'poor', 'carefully', 'custom', 'modern', 'thoroughly',
           'better', 'improve', 'improved', 'improving', 'adequate', 'adequ',
           'appropriate', 'inappropriate', 'improv', 'appropri', 'irregular',
           'abnormal', 'abnormalities', 'regularly', 'informal', 'inefficient'}
MODERATE = {'normal', 'normally', 'regular', 'valid', 'invalid', 'suitable',
            'effective', 'effectively', 'efficiently', 'accurately', 'badly',
            'improvement', 'improvements', 'improves', 'inadequate'}
