    elif word == 'improper':
        value = 5.49
    elif word == 'improperly':
        value = 4.40
    elif word in STRONG_ADVERBS:
        value = 1.84
    elif word in {'formal', 'formally', 'duly'}:
        value = 1.28
    elif word in QUALITY or word == 'incorrectly':
        value = 0.97
    elif word in MODERATE:
        value = 0.73
    elif word in MILD:
        value = 0.55
    elif word in {'impro', 'improvised'}:
        value = 2.4
    elif word in TRANSLATIONS:
        value = 1.30
    elif word in {'しっかり', 'しっかりと', 'ちゃんと', 'きちんと'}:
        value = 2.0
    elif word in {'正', '适', '잘', 'cải'}:
        value = 0.82
    elif word == 'بشكل':
