            value = 0.9
    elif raw == 'Pro':
        value = 0.84
    elif raw == 'ly':
        value = 1.0 if previous + raw in STRONG_ADVERBS else 0.17
    elif same_doc and raw.isalpha() and not value:
        completed = previous + raw.lower()
        if completed in {'improve', 'improving'}:
            value = 1.3
        elif completed in RELATED_WORDS:
            value = 0.65
        elif completed in {'formally', 'informally', 'optimally'}:
            value = 0.8
