help of', 'by means of', 'based on', 'according to'. The preceding verb
changes 'by': power/support is strongly positive, while a user, recipient,
or experiencer is negative. Instrumental relative clauses ('through which')
and non-instrumental senses ('use strict', 'use case', 'useless') reverse
sign. Other tokens are left near zero. These are lexical approximations,
not a parser or an exhaustive account of all meanings of these words.
"""
import re

READS = ()

# Approximate responses for families of verbs immediately before 'by'.
BY_FAMILIES = (
    ('powered governed constrained guided aided', 2.8),
    # An enabling or controlling source.
    (
        'supported controlled regulated limited influenced mediated '
        'connected helped',
        2.15,
    ),
    # Determination, measurement, and explanation.
    (
        'determined measured explained monitored imposed driven affected '
        'represented',
        1.5,
    ),
    (
        'given defined described provided shown specified indicated covered '
        'surrounded accompanied sponsored funded separated',
        1.15,
    ),
    # A user or experiencer, not a means.
    (
        'used utilized employed experienced faced shared borrowed hired suffered '
        'practiced',
        -2.5,
    ),
    # A recipient, evaluator, or bearer of something.
    (
        'adopted considered requested appreciated required purchased accepted '
        'incurred needed borne owed enjoyed feared misunderstood undergone '
        'regarded remembered worn',
        -1.4,
    ),
    (
        'obtained acquired taken received owned sold paid seen asked understood '
        'attended',
        -0.7,
    ),
    (
        'reported known developed found carried read signed submitted contributed '
        'incorporated awarded expected',
        -0.35,
    ),
)
BY_FAMILIES = tuple((set(words.split()), value) for words, value in BY_FAMILIES)

# These complete familiar expressions, not arbitrary token identities.
OF_NOUNS = {
    'help': 3.7, 'aid': 2.8, 'assistance': 2.4, 'use': 1.08,
    'needs': -1.5, 'terms': 0.65, 'because': 0.7, 'basis': 0.65,
    'way': 0.65, 'influence': 1.15, 'guidance': 1.15,
    'presence': 0.55, 'impact': 0.55, 'support': 0.55,
    'force': 0.55, 'independent': 0.55, 'form': 0.4,
    'effect': 0.4, 'effects': 0.4, 'function': 0.4,
    'lack': -0.34, 'free': 0.9,
}
TO_WORDS = {
    'according': 1.07, 'thanks': 2.2, 'pursuant': 1.4,
    'due': 0.44, 'owing': 0.44, 'access': 0.6, 'subject': 0.6,
    'subjected': 0.8, 'limited': -0.36, 'need': -0.12,
}
RELATIVE_PREPS = {
    'by': -1.8, 'through': -2.4, 'with': -1.75, 'via': -1.75,
    'upon': -1.35, 'under': -1.3, 'from': -0.75, 'after': -0.8,
    'during': -0.75, 'over': -0.65, 'against': -0.9,
    'without': -1.5, 'on': -0.35, 'to': -0.33, 'at': -0.2,
}
DEPENDENCE = set(
    'based dependent depending depend depends dependence dependency relying '
    'rely relies reliance reliant'.split()
)
# Some equivalent wording about means/use/assistance in other languages.
OTHER_LANGUAGES = {
    '用': 0.48, '使用': 0.72, '利用': 0.74, '通过': 0.34,
    '借助': 1.8, 'помощью': 3.6, 'помощи': 2.6,
    'hilfe': 1.8, 'bằng': 1.5, 'durch': 0.46, 'через': 0.51,
}


def by_value(previous, token, at_start):
    if token == 'BY':
        return 0.44
    for verbs, value in BY_FAMILIES:
        if previous in verbs:
            return value
    if previous in ('use', 'followed'):
        return -1.6
    if previous in ('divide', 'divided', 'step', 'sides'):
        return 0.15
    if previous in ('multiply', 'multiplied'):
        return -0.4
    if previous == 'characterized':
        return -0.15
    return 1.5 if at_start else (1.25 if token == 'By' else 0.65)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = re.findall(r'[a-z]+', tail.lower())
    if tail.rstrip().endswith(('.', '!', '?')) or tail.endswith('\n\n'):
        words = []
    previous = words[-1] if words else ''
    earlier = words[-2] if len(words) > 1 else ''
    instrumental_article = previous == 'the' and earlier in (
        'by', 'with', 'without', 'through'
    )
    value = OTHER_LANGUAGES.get(word, 0.0)
    if word == 'by':
        value = by_value(previous, token.strip(), not tail)
    elif word == 'using':
        value = 2.75 if previous == 'by' else (
            1.7 if previous == 'without' else 0.58
        )
    elif word in ('use', '-use'):
        value = 0.65
        if previous == 'can':
            value = 1.22
        elif instrumental_article or previous in (
            'by', 'with', 'without', 'through'
        ):
            value = 2.35 if previous == 'by' else 1.7
        elif previous == 'to':
            value = 0.8
        elif previous in ('in', 'for'):
            value = 0.25
        elif token == 'use' and tail:
            value = 0.22
        elif previous == 'the':
            value = 0.78
    elif word in ('uses', 'used', 'via', 'through'):
        value = {'uses': 0.31, 'used': 0.09, 'via': 1.25, 'through': 0.4}[word]
    elif word in ('help', 'aid', 'assistance'):
        value = {'help': 0.22, 'aid': 0.65, 'assistance': 0.15}[word]
        if instrumental_article or previous in ('with', 'without', 'whose'):
            value = 3.1 if word != 'assistance' else 1.2
        elif previous == 'the':
            value = 0.65 if word == 'help' else 0.9
        elif previous in ('can', 'need'):
            value = 0.9
    elif word == 'means':
        value = 2.9 if previous == 'by' else (
            1.6 if 'by' in words[-3:] else 0.1
        )
    elif word == 'of':
        value = OF_NOUNS.get(previous, 0.0)
        if previous == 'means':
            value = 3.0 if 'by' in words[-4:] else 1.0
    elif word == 'to':
        value = TO_WORDS.get(previous, 0.0)
    elif word in ('on', 'upon') and (
        previous in DEPENDENCE or (
            earlier in DEPENDENCE and previous.endswith('ly')
        )
    ):
        value = 0.95 if previous in ('based', 'dependent', 'relying') else 0.7
        if word == 'upon':
            value -= 0.4
    elif word in ('which', 'whom'):
        value = RELATIVE_PREPS.get(previous, 0.0)
    elif word == 'respect' and previous == 'with':
        value = -1.4
    elif word == 'terms' and previous == 'in':
        value = 0.67
    elif word in ('case', 'cases', 'strict') and previous == 'use':
        value = -2.1 if word == 'strict' else -3.0
    elif word == 'less' and tail.lower().endswith('use'):
        value = -2.0
    elif word in ('system', 'namespace') and previous in ('use', 'using'):
        value = -1.0
    elif word == 'in' and previous in ('use', 'used', 'using'):
        value = -0.33
    elif word in ('mere', 'merely', 'simply'):
        value = 0.28 if word == 'simply' else 0.9
        if previous == 'by':
            value += 1.65
    return (document, (tail + token)[-100:]), float(value)

programs.haiku:
"""Means and agency: fires on the word that introduces the means, instrument, agent or cause
of an action, such as 'by' in 'powered by' or 'controlled by', 'via', 'through', 'using',
'use', 'help' in 'with the help (of)', 'means' in 'by means (of)', 'to' in 'thanks to' or
'according to', and 'on' in 'based on' or 'depending on'.

Below zero on the relative 'which' after a means word ('through which'), on 'respect' in
'with respect to', and on 'by' after verbs of owning, following or opinion ('followed by',
'used by', 'feared by'). Near zero on 'by' after verbs of authorship or origin ('developed by',
'produced by'). Everything else is near zero.

Variance explained is about 0.3; the remainder is mostly 'of', 'to' and 'by' in contexts this
rule set does not describe."""
READS = ()

# means and instrument words, with their typical activation
MEANS = {
    " by": 0.6, "by": 0.8, " By": 1.3, "By": 1.1,
    " via": 1.4, "via": 0.6, " through": 0.4, " Through": 0.6,
    " using": 0.7, "using": 0.6, " Using": 0.6, " use": 0.7, " Use": 0.7, "use": 0.5,
    " utilizing": 1.2, " merely": 0.9, " mere": 0.9, " simply": 0.4,
    " durch": 0.5, " bằng": 1.6, "用": 0.5, "使用": 0.5, "借助": 2.0, " помощью": 3.7,
    " respect": -1.2, " help": 0.5,
}
# verbs before "by" that make it a physical or causal means (high)
MEANS_VERBS = {" governed", " constrained", " powered", " mediated", " controlled", " determined",
               " driven", " propelled", " limited", " protected", " supported", " assisted",
               " represented", " ruled", " aided", " provided", " given", " measured"}
# verbs of authorship or origin: "by" is near zero
ORIGIN_VERBS = {" developed", " produced", " characterized", " posted", " signed", " known",
                " created", " written", " published", " founded", " obtained", " spent"}
# verbs of owning, following or opinion: "by" is negative
NEGATIVE_VERBS = {" followed", " used", " purchased", " required", " owned", " occupied",
                  " feared", " respected", " admired", " regarded", " considered", " shared",
                  " adopted", " credited", " assumed", " contributed", " paid"}
# nouns after which "of" marks a means; words after which "to" marks a cause or source
HELP_NOUNS = {" help": 3.5, " means": 2.5, " assistance": 1.9, " use": 1.1, " influence": 1.0}
CAUSE_WORDS = {" according": 1.0, "According": 1.0, " According": 1.1, " thanks": 2.2, " due": 0.4}
# words after which "on" means "depending on" or "based on"
BASIS_WORDS = {" based", " Based", " depending", " Depending", " depends", " depend", " dependent",
               " relies", " relying", " reliance", " dependence", " heavily"}
MEANS_PREPS = {" through", " with", " by", " via"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    # the two previous words, only within the same document
    docs = prefix.document_ids
    prev = prefix.token_strings[-2] if len(prefix) > 1 and docs[-2] == docs[-1] else ""
    prev2 = prefix.token_strings[-3] if len(prefix) > 2 and docs[-3] == docs[-1] else ""
    if tok in (" help", "help") and prev in (" the", " their", " a") and prev2 == " with":
        return None, 3.3
    if tok == " means" and prev in (" by", "By", " By"):
        return None, 3.0
    if tok == " of" and prev in HELP_NOUNS:
        return None, HELP_NOUNS[prev]
    if tok == " to" and prev in CAUSE_WORDS:
        return None, CAUSE_WORDS[prev]
    if tok == " on" and prev in BASIS_WORDS:
        return None, 0.9
    if tok == " which" and prev in MEANS_PREPS:
        return None, -2.0
    if tok in (" by", "by"):
        if prev in MEANS_VERBS:
            return None, 2.0
        if prev in ORIGIN_VERBS:
            return None, 0.0
        if prev in NEGATIVE_VERBS:
            return None, -1.5
        if prev.endswith("ed"):
            return None, 0.8
    return None, float(MEANS.get(tok, 0.0))

programs.sol:
"""Approximate a contextual comma feature using familiar grammatical cues.

Standalone commas after ordinary content words are positive; discourse markers
such as "however" reverse the sign. Numeric commas are quiet, except after
month-and-day dates. Familiar word classes and word endings refine this rule.
Chinese grammatical endings modify ASCII/fullwidth commas. Arabic commas and
commas bundled with one newline have fixed positive levels; most other tokens
are silent. A 160-character tail resets at document boundaries.
"""
import re

READS = ()


def words(text):
    return frozenset(text.split())

CLAUSE_CONNECTIVES = words(
    'however moreover furthermore nevertheless nonetheless'
)
PARENTHETICAL_ADVERBS = words(
    'additionally alternatively also besides meanwhile finally unfortunately '
    'luckily fortunately rather likewise basically'
)
REASONING_TRANSITIONS = words(
    'thus therefore consequently similarly so then now instead indeed '
    'actually accordingly anyway further'
)
SHORT_DISCOURSE_WORDS = words(
    'hmm wait yes no yeah okay ok oh ah well but though still yet alright'
)
OTHER_ADVERBS = words(
    'today yesterday tomorrow earlier later again ago before after above '
    'below hence otherwise perhaps too'
)
SENTENCE_ADVERBS = words(
    'recently initially subsequently presently interestingly notably '
    'importantly'
)
ORDINALS = words(
    'first second third fourth firstly secondly thirdly lastly next overall'
)
PRONOUNS = words(
    'i you he she it we they me him her us them myself yourself himself '
    'itself'
)
DEMONSTRATIVES = words(
    'this that these those here there all'
)
FUNCTION_WORDS = words(
    'a an the and or of to in on at by for from with as which who be are do'
)
AUXILIARIES = words(
    'is was were am been being can could will would shall should may might '
    'must has have had'
)
CONVERSATIONAL_WORDS = words(
    'said say says saying know remember see sure sorry hi'
)
QUALIFIERS = words(
    'true false possible expected together like self'
)
TIME_AND_REFERENCE_NOUNS = words(
    'time day week month year night morning evening end way case result'
)
WEEKDAYS = words(
    'monday tuesday wednesday thursday friday saturday sunday'
)
NUMBER_WORDS = words(
    'zero one two three four five six seven eight nine ten hundred thousand '
    'million'
)
MONTHS = words(
    'january february march april may june july august september october '
    'november december'
)
PHRASES = ('for example', 'for instance', 'in fact', 'in addition', 'in particular',
           'of course', 'in general', 'on the other hand', 'in contrast')


def comma_value(text):
    clean = text.rstrip()
    if not clean:
        return 0.12
    words = re.findall(r'\w+', clean[-100:])
    if not words:
        return 0.15
    word = words[-1].lower()
    phrase = ' '.join(w.lower() for w in words[-4:])
    if clean[-1].isdigit():
        if len(words) > 1 and words[-2].lower() in MONTHS:
            return -0.4
        return 0.02
    if '\u4e00' <= clean[-1] <= '\u9fff':
        return chinese_comma(clean) + 0.15
    if word in CLAUSE_CONNECTIVES:
        return -0.90
    if word in PARENTHETICAL_ADVERBS:
        return -0.68
    if word in REASONING_TRANSITIONS:
        return -0.44
    if word in SHORT_DISCOURSE_WORDS:
        return -0.28
    if word in SENTENCE_ADVERBS:
        return -0.5
    if word in OTHER_ADVERBS:
        return -0.10
    if word in ORDINALS:
        return -0.3 if words[-1][:1].isupper() else 0.13
    if word in MONTHS or word in WEEKDAYS:
        return 0.20
    if any(phrase.endswith(p) for p in PHRASES):
        return 0.07
    if word in QUALIFIERS:
        return 0.3
    if word in TIME_AND_REFERENCE_NOUNS:
        return 0.45
    if (word in DEMONSTRATIVES or word in CONVERSATIONAL_WORDS
            or word in ('not', 'because')):
        return 0.07
    if word in AUXILIARIES:
        return 0.25
    if word in PRONOUNS or word in FUNCTION_WORDS:
        return 0.38
    if word in NUMBER_WORDS:
        return 0.50
    if not clean[-1].isalpha():
        return 0.2
    # Word shape approximates the distinction between nouns and verbs/adverbs.
    value = 0.4 + 0.03 * min(len(word), 10)
    if word.isascii():
        value += 0.24
    if word.endswith('s') and not word.endswith('ss'):
        value += 0.11
    if word.endswith('ed'):
        value -= 0.23
    if word.endswith('ing'):
        value += 0.05
    if word.endswith(('tion', 'sion', 'ness', 'ment', 'ity',
                      'ance', 'ence', 'ology')):
        value += 0.12
    if word.endswith(('ive', 'ous', 'al', 'able', 'ible', 'ful', 'less')):
        value -= 0.08
    if (word.endswith('ly')
            and word not in ('family', 'italy', 'assembly', 'july')):
        value -= 0.58
    return value


def chinese_comma(text):
    # Copula/demonstrative, time/place endings, verbs, and particles.
    last = text.rstrip()[-1:]
    if not last:
        return 0.0
    if last in '是此':
        return -0.85
    if last in '后時时前外下中里日月天候':
        return -0.55
    if last in '说為为來来':
        return -0.55
    if last in '了的上间間年面':
        return -0.25
    return 0.10


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if token == ',':
        value = comma_value(text)
    elif token == '،':
        value = 0.5
    elif token.startswith(',') and token.count('\n') == 1:
        value = 0.30
    elif token == '，':
        value = chinese_comma(text)
    elif ',' in token and '\n' not in token:
        value = 0.04
    else:
        value = 0.0
    return (doc, (text + token)[-160:]), float(value)

programs.luna:
"""Approximate the sparse punctuation response: commas usually get a positive
pulse, while the Chinese comma and some sentence-transition commas are negative.
The fixed pulse captures the broad cue, not the full context-dependent size."""
READS = ()

TRANSITION_ADVERBS = {
    "Alternatively", "Furthermore", "However", "Therefore", "Moreover",
    "Nevertheless", "Nonetheless", "Additionally", "Meanwhile", "Thus",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "，":
        return None, -0.55
    if token == ",":
        previous = ""
        if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip()
        value = -0.55 if previous in TRANSITION_ADVERBS else 0.55
        return None, value
    return None, 0.0

programs.sol:
"""Approximate strong clause/list-marker responses, not all lexical activity.

Semicolons and ellipses are boosted by the fraction of nearby letters
that are Chinese. Newline fusion changes punctuation strength; semicolons
fused with function-call parentheses are weakly negative. Smaller responses
cover ordinary Chinese punctuation and English contrast/list markers,
with capitalization distinguished. Recent enumeration commas boost 等
and distinguish list-like 等等; 等方面 has a fixed positive response.
Other tokens get 0.001. Document changes clear the sixteen-token history.
"""

READS = ()
CONTRAST_MARKERS = {
    ' while': 0.062, ' While': -0.166,
    ' however': 0.118, ' However': 0.063,
    ' yet': -0.133, ' Yet': -0.133,
    ' whereas': -0.035, ' Whereas': -0.173,
}
CHINESE_PUNCTUATION = {
    '。': 0.037, '，': -0.021, '：': -0.037, '、': 0.017,
    '！': 0.068, '？': 0.068, '（': -0.161,
    '“': 0.035, '”': -0.013, '「': -0.016, '」': -0.029,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    mark = text.strip()
    previous = history[-1] if history else ''
    last = previous[-1:]
    newline = '\n' in text or '\r' in text
    value = CHINESE_PUNCTUATION.get(mark, CONTRAST_MARKERS.get(text, 0.001))

    if text == ' while':
        if previous.strip() in {'that', 'but', 'But'}:
            value = -0.14
        elif last in {',', ';'}:
            value = 0.174
    elif text == ' etc':
        value = 0.162 if last in {',', ';'} else 0.041
    elif mark in {'等', '等方面', '等等'}:
        commas = ''.join(history).count('、')
        if mark == '等方面':
            value = 0.35
        elif mark == '等等':
            value = 0.0 if commas else -0.12
        else:
            value = min(0.40, 0.03 + 0.065 * commas) if commas else -0.06
    elif mark in {'；', ';', '…'} or (
            mark and len(mark) >= 2 and all(c in '.…·' for c in mark)):
        recent = ''.join(history)
        letters = max(sum(c.isalpha() for c in recent), 1)
        han = sum('\u3400' <= c <= '\u9fff' for c in recent) / letters
        if mark == '；':
            value = (0.39 + 0.77 * han if newline else
                     0.60 + 0.91 * han + 0.35 * last.isalpha())
        elif mark == ';':
            value = 0.05 + (0.70 if newline else 1.35) * han
        elif '·' in mark:
            value = 0.45 + 0.50 * han
        elif '…' in mark:
            value = (0.03 + 0.55 * han if len(mark) == 1 else
                     0.24 + 0.66 * han)
        elif len(mark) >= 4:
            value = 0.12 + 0.65 * han
        else:
            value = (0.05 + 0.47 * han if newline else
                     0.02 + 0.64 * han)
    elif ';' in mark and ')' in mark:
        value = (-0.18 if '()' in mark else
                 -0.10 if any(c in mark for c in '\"\'') else -0.015)
        if newline:
            value *= 0.37

    return (doc, (history + (text,))[-16:]), float(value)

