"""Use semicolons and ellipses as weak cues for positive activation.

These marks appeared among harvested high activations, but punctuation alone
is unreliable. The rough positive estimates are therefore scaled down to a
tenth; all other tokens predict zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    estimate = 0.0

    if "；" in token:
        estimate = 1.1 if "\n" in token else 1.85
    elif ";" in token:
        estimate = 0.52
    elif "……" in token or "..." in token:
        if "\n" in token:
            estimate = 0.41
        else:
            estimate = 0.91 if "……" in token else 0.82

    return None, 0.1 * estimate

"""Track a word across token pieces and mark speech, reporting, and debate vocabulary."""
READS = ()
ROOTS = (
    'say', 'said', 'tell', 'speak', 'spoke', 'report', 'claim', 'state',
    'remark', 'argu', 'discuss', 'debat', 'convers', 'communicat',
    'comment', 'editorial', 'complaint', 'opin', 'mention', 'suggest',
    'call', 'controvers', 'discourse', 'discur',
)

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, word = carry if carry is not None else (doc, '')
    if doc != old_doc:
        word = ''
    for char in prefix.token_strings[-1].lower():
        if char.isalpha():
            word += char
        else:
            word = ''
    active = any(word.startswith(root) for root in ROOTS)
    return (doc, word), (0.35 if active else 0.0)

programs.sol:
"""Predict the component's main positive response from AD spelling.

Training measurements are largest on bare ad/AD and short -ad chunks.
Longer tokens usually respond less. Case, word-boundary spaces, vowel
pairs and selected word stems distinguish stronger and weaker variants.
Short -ed chunks have a smaller response. Cyrillic/Arabic ad spellings
and the Chinese words for advertisement are included explicitly.
Only the current token is used; context effects and most small or
negative background activations are deliberately left unexplained.
"""
import string

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip(string.whitespace + string.punctuation)
    word = text.lower()
    spaced = token.startswith(' ')
    value = 0.0
    if word in ('ad', 'ads'):
        if text.isupper():
            value = 4.3 - 1.0 * spaced
        elif text.istitle():
            value = 3.8 - 0.1 * spaced
        else:
            value = 4.6 - 0.5 * spaced
        if word == 'ads':
            value -= 0.9 if spaced else 0.3 * (not text.istitle())
    elif word in ('pad', 'pads'):
        value = 4.0 if text.istitle() else 4.9
    elif word == 'had':
        value = 1.06 if token == ' had' else 2.1
    elif word == 'dad':
        value = 1.4
    elif word in ('ead', 'oad'):
        value = 3.2
    elif 'ead' in word or 'oad' in word:
        value = 1.9 if word == 'dead' else 0.0
        if word in ('lead', 'leads', 'bead', 'beads', 'bread', 'road', 'roads'):
            value = 0.8
    elif 'ad' in word:
        before, after = word.rsplit('ad', 1)
