def activation_of(token: str) -> float:
    letters = re.sub(r"[^a-z]", "", token.lower())
    if "ad" not in letters:
        return 0.0
    if len(letters) == 2:
        return 4.3
    if len(letters) == 3:
        return 1.6
    if len(letters) == 4:
        return 0.8
    return 0.4


def step(carry, prefix, upstream):
    return None, float(activation_of(prefix.token_strings[-1]))

