programs.sol:
"""A spelling-based approximation to a short 'on'-syllable response.

Bare fragments are stronger than space-prefixed words; long words are weaker.
Common unstressed endings and JSON are excluded.  The preposition 'on' is
weaker after verbs that conventionally take it ('based on', 'depends on').
Small spelling rules also cover accented vowels and Cyrillic counterparts.
These are approximate responses, not a pronunciation dictionary.
"""
import re
from functools import lru_cache
import unicodedata

READS = ()
CYRILLIC = str.maketrans({
    'о': 'o', 'н': 'n', 'р': 'r', 'м': 'm', 'к': 'k', 'с': 's',
    'т': 't', 'п': 'p', 'л': 'l', 'г': 'g', 'б': 'b', 'ф': 'f',
    'д': 'd', 'а': 'a', 'и': 'i', 'е': 'e', 'в': 'v', 'з': 'z',
    'у': 'u', 'й': 'y', 'ц': 'ts', 'ч': 'ch', 'ш': 'sh',
    'щ': 'shch', 'х': 'kh', 'я': 'ya', 'ю': 'yu', 'ё': 'yo',
    'ы': 'y', 'э': 'e', 'ь': '', 'ъ': '',
})
UNSTRESSED_ENDINGS = (
    'common', 'person', 'reason', 'season', 'lesson', 'prison',
    'button', 'cotton', 'london', 'psilon', 'region', 'union',
    'million', 'billion', 'trillion', 'opinion',
)
PARTICLES = {'proton', 'neutron', 'electron', 'photon', 'positron'}
# Frequent prefixes/function words containing a short written 'on'.
SHORT_ON = {
    'con': (0.5, 1.4), 'don': (1.2, 3.3), 'son': (1.5, 2.35),
    'non': (1.3, 1.85), 'von': (1.05, 2.5), 'won': (1.9, 3.0),
    'ion': (2.0, 2.1),
}


def normalize(text):
    text = text.lower().translate(CYRILLIC)
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if unicodedata.category(c) != 'Mn')


@lru_cache(maxsize=32768)
def spelling_value(token):
    raw = token.strip()
    plain = raw.strip('._-\'"([]{}<>:/\\')
    word = normalize(plain)
    spaced = token[:1].isspace()
    if raw.endswith('ون'):  # Arabic waw + nun, the written '-un' ending.
        return 1.6 * 0.7**max(0, len(raw)-2)
    if 'on' not in word:
        return 0.004
    plural = word.endswith('ons')
    if plural:
        word = word[:-1]
    scale = 0.8 if plural else 1.0
    if word.endswith(UNSTRESSED_ENDINGS) or word.endswith('json'):
        return 0.04
    if word.endswith(('tion', 'sion', 'cion', 'xion', 'shion')):
        return 0.04
    if word == 'on':
        if normalize(plain) != plain.lower():
            value = 1.3 if spaced else 2.7 if plain == 'он' else 2.1
        elif plain == 'On':
            value = 2.35 if spaced else 2.5
        else:
            value = 1.95 if spaced else 3.5
        if plain != raw and not spaced:
            value *= 0.85
        return value * scale
    if word in {'one', 'ones', 'once', 'only', 'none', 'done', 'online'}:
        return 0.04 if spaced or raw[:1].isupper() else 0.8
    if raw.lower() == 'ión':  # Spanish nominalization suffix.
        return 0.45
    if word in PARTICLES:
        return 2.5 * 0.75**max(0, len(word)-6) * scale
    if word.endswith('on'):
        if word == 'upon':
            value = 1.4
        elif word == 'oon':
            value = 0.7 if spaced else 1.5
        elif len(word) == 3:
            if any('CYRILLIC' in unicodedata.name(c, '') for c in raw):
                value = 1.5 if spaced else 2.8
            else:
                value = SHORT_ON.get(word, (2.9, 3.9))[not spaced]
                if spaced and raw[:1].isupper() and word in {'don', 'son'}:
                    value += 0.7
                if word == 'ion' and raw.isupper():
                    value = 0.3
        elif word.endswith('ion'):
            value = 2.3 * 0.75**max(0, len(word)-5)
        else:
            value = (2.5 if spaced else 3.5) * 0.68**max(0, len(word)-4)
            if word.endswith(('oon', 'icon')) or word == 'aron':
                value *= 0.55
            if word.endswith(('thon', 'sson')):
                value *= 0.65
            if word.endswith('ieron'):  # Romance past-tense verb ending.
                value *= 0.25
        return value * scale
    if word.endswith(('ong', 'ongs')):
        return 0.04
    if word.startswith('on'):
        return 0.85
    value = 0.6 * 0.55**max(0, len(word)-4)
    return value * (0.25 if word.startswith('cons') else 1.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = spelling_value(token)
    if token == ' on':
        if previous == 'based':
            value = 0.85
        elif re.fullmatch(r'focus(ed|es|ing)?', previous):
            value = 0.95
        elif re.fullmatch(r'depend(s|ing|ent)?', previous):
            value = 1.1
        elif re.fullmatch(r'work(s|ed|ing)?|rel(y|ies|ying)|click(s|ed|ing)?',
                          previous):
            value = 1.45
    elif token in {'ion', 'ions'} and previous.endswith(('t', 's')):
        value = 0.7 if token == 'ion' else 0.5
    elif token == 'on' and previous.endswith('on'):
        value = 5.0
    # Keep only the unfinished word, and reset it at document boundaries.
    match = re.search(r'[a-z]+$', previous + token.lower())
    word = match.group()[-64:] if match else ''
    return (doc, word), float(value)

