programs.sol:
"""A partial spelling-and-boundary approximation.

Track the last ASCII word fragment, resetting at each document. Attached
Greek/Latin noun endings lean negative; single-vowel pieces and -at/-ie
fragments lean positive. Stem length modulates these tendencies. Paths,
possessives, heading punctuation and text delimiters have separate weak
backgrounds. This deliberately leaves most word-specific responses unmodelled.
"""
import re

READS = ()

DISEASE_ENDINGS = ('osis', 'oma', 'algia', 'thermia', 'oxia', 'opia', 'plasia')
GREEK_ENDINGS = ('graphy', 'trophy', 'pathy', 'phobia', 'phila', 'phils', 'phyll')
PARTICLE_STEMS = ('phon', 'cod', 'glu', 'bos', 'lept', 'nucle', 'mes', 'bary',
                  'ferm', 'gravit', 'xen', 'hadr')
VOWELS = set('aeiouy')


def describe(stem, token):
    """Return an orthographic/morphological class, and stem length."""
    text = token.strip()
    if stem and token.isascii() and token.isalpha():
        word = (stem + token).lower()
        length = min(len(stem), 8)
        if len(token) <= 7:
            for ending in DISEASE_ENDINGS:
                if word.endswith(ending) and len(word) > len(ending) + 1:
                    return 'medical_' + ending, length
            for ending in GREEK_ENDINGS:
                if word.endswith(ending) and len(word) > len(ending) + 1:
                    return 'greek', length
            if word.endswith(('larynx', 'pharynx', 'syrinx')):
                return 'anatomy', length
        if token in ('on', 'ons') and stem.lower().endswith(PARTICLE_STEMS):
            return 'particle', length
        if token in ('s', 'es'):
            cluster = (len(stem) > 1 and stem[-1].lower() not in VOWELS
                       and stem[-2].lower() not in VOWELS)
            return 'plural_cluster' if cluster else 'plural', length
        if token in ('ms', 'ism', 'isms', 'ics', 'ists'):
            return 'abstract_plural', length
        if token in ('us', 'um', 'ium', 'ae'):
            return 'latin_noun', length
        if token in ('on', 'ons', 'ine', 'ines', 'ase', 'ases', 'oid', 'oids'):
            return 'scientific_noun', length
        if token in ('ia', 'ria', 'ian', 'ians'):
            return 'classical_name', length
        if token in ('a', 'e', 'o'):
            return 'vowel_fragment', length
        if token in ('ie', 'at'):
            return 'unfinished_stem', length
        if token in ('or', 'ors', 'en'):
            return 'agent', length
        if token in ('ly', 'less', 'ical'):
            return 'modifier', length
    if re.match(r'^/[A-Za-z]', token):
        return 'slash_word', min(len(token) - 1, 8)
    if re.match(r'^_[A-Za-z]', token):
        return 'underscore_word', min(len(token) - 1, 8)
    if re.match(r'^-[A-Za-z]', token):
        return 'hyphen_word', min(len(token) - 1, 8)
    if token == '\r':
        return 'carriage_return', 0
    if token.startswith('<|'):
        return 'delimiter', 0
    if token in ("'s", '’s'):
        return 'possessive', 0
    if text and set(text) == {'#'}:
        return 'heading', 0
    return 'background', 0


# Each class maps to (offset, change per preceding letter).
PARAMETERS = {
    'underscore_word': (-0.0196, 0.0002),
    'background': (-0.0022, 0.0),
    'hyphen_word': (-0.0147, -0.0002),
    'scientific_noun': (-0.0128, -0.0071),
    'slash_word': (-0.0072, -0.0065),
    'delimiter': (-0.0172, 0.0),
    'possessive': (-0.0132, 0.0),
    'plural': (0.0134, -0.0051),
    'plural_cluster': (0.0129, -0.0052),
    'modifier': (0.0299, 0.0001),
    'classical_name': (0.0173, -0.0097),
    'abstract_plural': (-0.023, -0.0082),
    'unfinished_stem': (-0.0211, 0.0137),
    'agent': (-0.0129, -0.0034),
    'heading': (-0.0187, 0.0),
    'latin_noun': (-0.0, -0.0071),
    'vowel_fragment': (0.0166, 0.0028),
    'particle': (-0.3429, 0.0372),
    'greek': (0.1106, -0.0359),
    'medical_osis': (-0.0129, -0.0309),
    'carriage_return': (-0.1207, 0.0),
    'medical_oma': (-0.1243, -0.0074),
    'medical_oxia': (-0.0136, -0.068),
    'anatomy': (-0.0437, -0.0582),
    'medical_plasia': (-0.0045, -0.0211),
    'medical_opia': (-0.25, 0.0),
    'medical_thermia': (-0.25, 0.0),
    'medical_algia': (-0.25, 0.0),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    stem = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    kind, length = describe(stem, token)
    offset, slope = PARAMETERS.get(kind, (-0.0025, 0.0))
    value = offset + slope * length
    stem = re.split(r'[^A-Za-z]', stem + token)[-1][-40:]
    return (doc, stem), float(value)

