programs.sol:
"""An orthographic p detector, strongest in short p-ending fragments.

Strength varies with the preceding letter; longer prefixes and suffixes weaken
it. Latin p and Cyrillic pe are treated alike, and doubled p counts once.
An isolated p continuing a word/acronym is stronger than a standalone p.
Greek pi and repeated indentation whitespace have separate small responses.
The rule is approximate: it does not memorize whole-word/token activations.
"""
from functools import lru_cache
from math import exp

READS = ()
CYRILLIC = str.maketrans("паеиоуымнрстхлдфгвбз", "paeiouymnrsthldfgvbz")
# Spelling classes for the letter immediately before p.
NEIGHBORS = (
    ("ao", 1.559), ("e", 2.098), ("i", 1.849), ("u", 1.036),
    ("y", 1.616), ("m", 1.768), ("n", 2.689), ("s", 1.660),
    ("r", 3.507),
)
PREFIX_SCALE = (1.189, 1.0, 0.747, 0.575, 0.386, 0.180)
SUFFIXES = (("ing", 0.509), ("ed", 0.382), ("s", 0.557),
            ("e", 0.143), ("y", 0.284))

@lru_cache(maxsize=8192)
def spelling(token):
    raw = token.strip().lstrip("._/-([<\\=")
    word = raw.lower().translate(CYRILLIC)
    if token.isspace():
        if "\t" in token:
            return -0.031 + 0.111 * min(max(token.count("\t") - 1, 0), 6)
        if token.count("\u00a0") >= 2:
            return 0.500
    if word == "π":
        return 0.726
    last = word.rfind("p")
    if last < 0:
        return 0.0
    first = last
    while first > 0 and word[first - 1] == "p":
        first -= 1
    before, after = word[:first], word[last + 1:]
    prev = before[-1:]
    value = 1.189 if not before else 2.146
    for letters, strength in NEIGHBORS:
        if prev and prev in letters:
            value = strength
            break
    value *= PREFIX_SCALE[min(len(before), 5)]
    suffix_scale, rest = (1.0, 0) if not after else (0.124, len(after) - 1)
    for ending, scale in SUFFIXES:
        if after.startswith(ending):
            suffix_scale, rest = scale, len(after) - len(ending)
            break
    value *= suffix_scale * exp(-0.275 * rest)
    if token[:1].isspace():
        value *= 0.886
    if raw.isupper() and len(raw) > 1:
        value *= 1.189
    if "п" in token.lower() and len(before) >= 2:
        value *= 1.407
    if not before and after:
        value *= 0.264
    if before == "a" and last > first:
        value *= 0.038
    if len(before) >= 3 and prev in "hlt":
        value *= 0.077
    if len(before) >= 2 and prev == "x":
        value *= 0.479
    return float(value)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = spelling(token)
    same_doc = (len(prefix.token_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    if token in {"p", "P"}:
        left = prefix.token_strings[-2][-1:] if same_doc else ""
        if token == "P":
            value = 2.70 if left.isupper() else 1.55 if left.isalpha() else 1.20
        else:
            value = 2.35 if left.isalpha() and left.lower() != "p" else 1.45
    return None, float(value)

"""A lexical detector centred on 假: false/pretend, and leave/vacation.

The strongest negative response is to 假 itself. Smaller responses recognize
Boolean literals, falsity/pretence words, holidays, and borrowing vocabulary.
This is word recognition, not reasoning about whether a statement is true.
A few incomplete UTF-8 prefixes also fire, including the prefix of flag emoji.
The amplitudes approximate training averages; other tokens get zero. Stored
byte fragments and the previous word reset at document boundaries.
"""
import re

READS = ()

# Falsehood, hypotheses, holidays/leave, borrowing, and stopping (Chinese/Japanese).
CJK = {
    '假': -7.68, '假设': -2.0, '假設': -2.0, '虚假': -3.0,
    '假如': -2.7, '假冒': -2.1, '假期': -4.5, '假日': -4.2,
    '度假': -1.9, '暑假': -3.0, '寒假': -3.4, '放假': -3.6,
    '请假': -3.8, '休假': -2.4, '节假日': -2.7, '节日': -1.05,
    '春节': -0.85, '真的': -0.45, '嘘': -0.45,
    '借': -1.7, '借款': -0.9, '借錢': -0.9, '借用': -0.8,
    '借助': -0.8, '借口': -0.8, '租': -0.55,
    '休': -0.7, '休み': -1.3, '闲': -0.5, '閒': -0.65,
    '周末': -1.0, '停': -0.8, '暂停': -1.6, '停止': -0.35,
    '仮': -3.8, '暇': -1.0, '伪': -1.5,
}

# Named word classes, not a table of arbitrary vocabulary IDs.
WORD_CLASSES = (
    ({'fake', 'faux', 'hoax', 'untrue', 'falsehood'}, -0.8),
    ({'pseud', 'pseudo', 'seud'}, -1.2),
    ({'borrow', 'borrowed', 'borrowing'}, -0.75),
    ({'borrower', 'borrowers'}, -0.35),
    ({'mock', '.mock', '(mock'}, -0.35),
    ({'dummy', 'ummy', '(dummy'}, -0.6),
    ({'hypothesis', 'hypothetical', 'hypoth', 'hypotheses'}, -0.5),
    ({'bias', 'biased'}, -0.5),
    ({'pretended', 'pretending', 'illusion', 'illusions'}, -0.5),
    ({'fictional', 'artificial', 'nonsense', 'pretend'}, -0.35),
    ({'festive', 'anniversary', 'birthdays', 'occasion'}, -0.45),
    ({'birthday'}, -0.3),
    ({'fals', 'alse'}, -0.4),
    ({'falsely'}, -1.08),
    ({'seudo'}, -0.75),
    ({'giả'}, -1.8),              # Vietnamese: false/pretend.
    ({'празд'}, -1.0),            # Russian holiday word stem.
    ({'really', 'actually'}, 0.15),
)

FALSE_PREFIX = '假'.encode()[:2]
JAPANESE_PREFIX = '仮'.encode()[:2]
FLAG_PREFIX = '🇦'.encode()[:3]

# Four incomplete tokenizer pieces, used only to recover their UTF-8 bytes.
BYTE_PREFIXES = {
    4891: b' ' + FALSE_PREFIX[:1],
    6142: JAPANESE_PREFIX,
    11162: b' ' + FLAG_PREFIX[:2],
    48591: FALSE_PREFIX,
}


def byte_piece(token_id):
    if token_id in BYTE_PREFIXES:
        return BYTE_PREFIXES[token_id]
    # The tokenizer's first 256 IDs enumerate its single-byte alphabet.
    for limit, offset in ((94, 33), (106, 67), (188, 68),
                          (221, -188), (255, -94), (256, -82)):
        if token_id < limit:
            return bytes([token_id + offset])
    return b''


def fragment_response(raw):
    if raw == b' ' + FALSE_PREFIX:
        return -3.9
    if raw == FALSE_PREFIX:
        return -1.15
    if raw.endswith(JAPANESE_PREFIX):
        return -1.3
    if raw.endswith(FLAG_PREFIX):
        return -1.2
    return None


def lexical_response(token, word, previous):
    lower = word.lower()
    literal = re.fullmatch(r'([=(:.,_>/]*)(true|false)', lower)
    if literal:
        wrapper, truth = literal.groups()
        if wrapper:
            return -1.1
        if word.isupper():
            return -0.9
        if truth == 'true':
            return -1.0
        return -1.1 if word[:1].isupper() else -1.23
    if lower in {'.isfalse', '.istrue', 'isfalse', 'istrue'}:
        return -0.9
    if word in CJK:
        return CJK[word]
    if word in {'设', '設'} and previous == '假':
        return -1.8  # The second piece of 假设/假設, 'suppose'.
    if lower in {'holiday', 'oliday', 'olidays'}:
        if lower != 'holiday':
            return -2.4
        if word[:1].islower():
            return -3.0 if token.startswith(' ') else -2.7
        return -2.4 if token.startswith(' ') else -1.9
    if lower == 'holidays':
        return -2.3 if word[:1].isupper() else -1.9
    if lower in {'vacation', 'vacations'}:
        return -1.4
    if lower in {'christmas', 'thanksgiving'}:
        return -1.0
    if lower in {'halloween', 'easter', 'weekend', 'weekends'}:
        return -0.5
    if word == 'Mock':
        return -0.6
    for words, value in WORD_CLASSES:
        if lower in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous, pending = carry[1:] if carry and carry[0] == doc else ('', b'')
    token = prefix.token_strings[-1]
    word, raw = token.strip(), b''
    if '\ufffd' in token:
        piece = byte_piece(int(prefix.token_ids[-1]))
        raw = (pending + piece)[-8:] if piece else b''
        # Full-prefix decoding can reveal a character a byte token completes.
        if carry and carry[0] == doc:
            word = prefix.text_prefixes[-1][-1:]
    value = fragment_response(raw)
    if value is None:
        value = lexical_response(token, word, previous)
    if raw and '\ufffd' not in raw.decode('utf-8', 'replace'):
        raw = b''
    return (doc, word, raw), float(value)

