import re

READS = ()
CODE = re.compile(
    r'(?:\b|\\[nt])(?:def |class |import |return |func |fn |impl |'
    r'let |pub |const |var |package )'
)
TEX = re.compile(
    r'\\(?:begin|end|frac|sqrt|newcommand|text|left|right|mathrm|mathbf|'
    r'hline|alpha|beta|gamma|sigma|tau|vec|sum|int)\b'
)
EXCEPTION = re.compile(r'[A-Z][A-Za-z]*Error$')
RUST_TYPES = {'Option', 'Result', 'Vec', 'Box', 'Err', 'Ok', 'HashMap', 'HashSet'}
RUST_WORDS = {'crate', 'crates', 'serde', 'dyn', 'derive', 'PartialEq', 'Into', 'boxed'}


def response(token, recent, first):
    s = token.strip()
    low = s.lower()
    if low in ('error', 'errors'):
        if s.isupper():
            return -0.76
        value = -0.80 if low == 'errors' else -1.08
        return value - (0.13 if CODE.search(recent) else 0.0)
    if low.strip('_/-()') in ('error', 'errors'):
        return -1.0
    if s.endswith('Errorf'):
        return -1.0 if s.startswith('.') else -0.7
    if low in ('.error', '.errors'):
        return -0.9 if s[1].isupper() else -0.71
    if EXCEPTION.fullmatch(s):
        return -0.63
    if '::' in s:
        if s == '::':
            return -1.10 if token.startswith(' ') else -0.94
        return -0.74
    if s.startswith('///'):
        return -0.27
    if '//' in s and '://' not in s:
        return -0.65
    if s.startswith('#['):
        return -0.59
    if s == '#':
        if first:
            return 0.127
        if TEX.search(recent) or recent.endswith(']('):
            return 0.0
