RAISED = {
    '⁰': 4.2,
    '¹': 4.4,
    '²': 4.85,
    '³': 5.1,
    '⁴': 5.9,
    '⁵': 6.1,
    '⁶': 6.1,
    '⁷': 6.1,
    '⁸': 5.3,
    '⁹': 5.1,
