    token = prefix.token_strings[-1]
    new_tail = (tail + token)[-32:]
    if token == '�' and tail:
        token = prefix.text_prefixes[-1][-1:]  # completed Unicode character
        new_tail = (tail.rstrip('�') + token)[-32:]
    strength = 0.0
    raised = next((c for c in token if c in RAISED), None)
    exponent = EXPONENT.search(tail)
    if raised:
        strength = RAISED[raised]
        if tail.endswith('✝'):
            strength += 1.5 if raised in '¹²³' else 0.3
        elif TRIG.search(tail):
            strength += 1.6
    elif token == '�' and tail.endswith('✝'):
        strength = 3.0  # incomplete raised suffix of a Lean identifier
    elif token in ('⁻', '⁺', 'ⁿ', 'ⁱ'):
        strength = 2.6 if token in ('⁻', '⁺') else 4.0
    elif any(c in '₀₁₂₃₄₅₆₇₈₉' for c in token):
        strength = 0.65
    elif tail.endswith('.sup.') and token.isascii() and token.isdigit():
        strength = 3.5  # plain-text markup for a superscript
    elif exponent:
        opening, sign, digits = exponent.groups()
        if token.isascii() and token.isdigit():
            base = tail[:exponent.start()]
            strength = 5.55 if token == '2' else 5.95
            strength += 0.4 * base[-1:].isdigit() + 1.5 * bool(TRIG.search(base))
            strength -= 1.4 * ('{' in opening) + 1.9 * ('(' in opening)
            strength -= 1.7 * (' ' in opening)
            if sign:
                strength = 2.8 if token == '1' else 2.4
            if digits:
                strength *= 0.43 * 0.35 ** (len(digits) - 1)
        elif not digits:
            if len(token) == 1 and token.isascii() and token.isalpha():
                strength = 1.7 if sign else 4.6 - 1.3 * ('{' in opening)
                strength -= 1.6 * ('(' in opening)
            elif token.startswith('{') or token in ('\\', '*', '('):
                strength = 1.9 if '\\' in token else 2.5
            elif token.startswith(('-', '+')):
                strength = 5.0 if token == '-' else 2.7
            elif token == '_^':
                strength = 3.0  # caret eyes in ^_^ emoticons
            elif token.isspace() and '\n' not in token:
                strength = 2.2
    elif tail.endswith('√') and token.isascii() and token.isdigit():
        strength = 0.7
    elif token.strip() in ('squared', 'cubed'):
        strength = 0.8
