        k = w.rfind('k')
        before = w[k - 1] if k else ''
        boundary = s[:1].isspace() or not s[:1].isalnum()
        # Ignore attached punctuation when recognizing common word families.
        word = w.lstrip('._/(-')
        weak = word.startswith(WEAK) and word.count('k') == 1
        if k == len(w) - 1:
            if n == 1:
                return -1.38 if boundary else -2.03
            if n <= 3:
                if before == 'c':
                    return -1.35
                if before in 'dfmpqtvwxz':
                    return -3.75
                return -3.0 if before in 'ul' else -2.3
            if weak or n > 7:
                return -0.1 if weak else -0.3
            if word.startswith(EVERYDAY):
                return -0.8
            return -1.0 if before == 'c' else -1.45
        if k == 0:
            if w.startswith('kn'):
                return 0.07
            if w.startswith(('key', 'keep', 'kept')):
                return -0.72
            if n <= 3 and not any(c in 'aeiou' for c in letters):
                return 0.1 if boundary else -0.1
            return -0.58 if n == 2 and not boundary else -0.3
        if weak:
            return -0.38 if before == 'n' else -0.1
        if word.startswith(('work', 'homework')):
            return -0.6 if n <= 6 else -0.13
        return -0.84 if n <= 8 else -0.5
    if 'к' in w:
        return -1.4 if w.endswith('к') else -0.55
    if 'κ' in w:
        return -1.0
    if any(c in w for c in 'كکक'):
        return -1.8 if w[-1:] in 'كکक' else -0.6
    if any(c in w for c in KANA):
        if w[-1:] not in KANA:
            return -0.2
        if len(w) > 1:
            return -1.0 if 'ァ' <= w[-1] <= 'ヺ' else -0.65
        if w in 'かカこコ':
            return -0.4
        return -1.0
    if any(c in s for c in 'กค기키'):
        return -0.8
    if 'q' in w:
        return -0.3 if len(w) <= 3 and w not in ('que', 'qui') else -0.08
    if '``' in s:
        return -0.44
    if '✔' in s or '✓' in s:
        return -1.2 if '✔' in s else -0.5
    return -0.007


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, s), float(spelling(s, previous))

programs.haiku:
"""k-sound (any script): tokens whose k closes a syllable are strongly negative."""
READS = ()
K_LETTERS = set("kKкКκΚكک")
VOWELS = set("aeiouyаеиоуыэюяäöüéèàαειου")
EXEMPT = {"make", "making", "makes", "back", "think", "thinks", "know", "knew", "known", "network", "workspace", "working", "kind", "knowledge"}
def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if not any(c in K_LETTERS for c in s):
        return None, 0.0
    if s in EXEMPT or s.startswith("kn"):
        return None, 0.0
    if s in ("k", "к", "κ"):
        return None, -1.8
    i = max(j for j, c in enumerate(s) if c in K_LETTERS)
    prev = s[i - 1:i]
    nxt = s[i + 1:i + 2]
    if nxt == "" or nxt not in VOWELS:
        return None, -0.8 if prev in ("c", "r", "n", "") else -1.6
    return None, -0.6

programs.sol:
"""Approximate v/V spelling detector with a one-token continuation echo.

Short v-initial pieces, repeated v's, and document-initial v's respond strongly.
Common complete v-word families are weaker than explicit spelling fragments;
velocity and voltage words are stronger. Cyrillic в has a weaker counterpart.
End-of-text has an independent positive response. Other lexical variation is
not modeled. Carry stores just the previous token and resets across documents.
"""
from string import punctuation, whitespace

READS = ()
SEPARATORS = punctuation + whitespace + '‘’“”'
COMMON_V_FAMILIES = ('valu', 'vari', 'vect', 'view', 'video', 'valid', 'virt')
COMMON_V_WORDS = frozenset(('very', 'via', 'void', 'von', 'var', 'vary'))
# Speed and electrical potential, both conventionally associated with v/V.
V_QUANTITY_STEMS = ('veloc', 'volt')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    text = prefix.token_strings[-1]
    word = text.lower().lstrip(SEPARATORS)
    old_word = previous.lower().lstrip(SEPARATORS)
    length = len(word)
    value = 0.0

    if text == '<|endoftext|>':
        value = 0.89
    elif word.startswith('v'):
        if length == 1:
            value = 0.65
        elif length == 2:
            value = {'a': 0.46, 'e': 0.56, 'i': 1.03,
                     'o': 0.80}.get(word[1], 0.48)
        elif length == 3:
            value = {'a': 0.30, 'e': 0.54, 'i': 0.45,
                     'o': 0.41, 'u': 0.37}.get(word[1], 0.23)
        else:
            value = 0.20 if length < 6 else 0.17
            value += {'e': 0.08, 'i': 0.04, 'o': 0.04,
                      'u': 0.28}.get(word[1], 0.0)
        value += 0.08 * ('V' in text)
        value -= 0.04 * (not text[:1].isspace())
        value += 0.50 * (word.count('v') > 1)
        if word in COMMON_V_WORDS or word.startswith(COMMON_V_FAMILIES):
            value -= 0.25
        value -= 0.16 * (word == 'val')  # abbreviation of value
        value += 0.56 * word.startswith(V_QUANTITY_STEMS)
        if word == 've' and text.lstrip()[:1] in ("'", '’'):
            value -= 0.30  # contracted "have"
        if first:
            if length == 1 and text[:1].isalpha():
                value = 2.63 + 0.26 * ('V' in text)
            else:
                value += 1.30 if length == 1 else 0.40
    elif length == 2 and word.endswith('v'):
        value = {'a': -0.14, 'e': 0.13, 'i': -0.03,
                 'o': 0.12, 'u': 0.17}.get(word[0], 0.0)
    elif word.startswith('в'):
        value = 0.11
    elif word.endswith('в'):
        value = -0.06
        if length == 2:
            value = {'а': -0.18, 'и': -0.25,
                     'о': 0.04}.get(word[0], value)

    # Echo a final v into a following spelling fragment, not across whitespace.
    beginning = text[:1].lower()
    continues = beginning.isalnum()
    if old_word.endswith('v'):
        if continues:
            vowel = beginning in 'aeiouy'
            if beginning.isdigit():
                value += {'0': 0.29, '1': 0.25}.get(beginning, 0.20)
            elif vowel:
                value += {'a': 0.07, 'e': 0.40, 'i': 0.31,
                          'o': 0.37, 'u': 0.40, 'y': -0.10}[beginning]
                value += 0.18 * (len(old_word) <= 3)
            else:
                value += 0.22 + 0.18 * (beginning in 'lr')
            if old_word == 'v':
                value += 0.11 * beginning.isalpha() + 0.15 * vowel
            value -= 0.18 * (length >= 4)
            value += 1.16 * ('v' in word)
        else:
            value += 0.04
    elif 'v' in old_word[-3:] and continues:
        value += 0.08
    if old_word.endswith('в') and continues:
        value += 0.06 + 0.30 * (old_word == 'в')
        value += 0.16 * (beginning in 'еио')
    return (doc, text), float(value)

programs.haiku:
"""Layer-0 MLP unit 3519: a "the letter v" detector.

It fires on the current token when that token's text is built around the letter v:
  * the end-of-text token (documents end there), strongest of the group;
  * a lone "v" or "V" piece (" v", "V", "v");
  * a piece that starts with v, such as "vi", "vo", "ve", "vol", "velocity";
  * a piece that ends with v, such as "ov", "iv", "oy" in "envoy".
It stays near zero when v sits in the middle of a piece ("river", "everyone", "div"),
and gives only a small value to English "va-" words ("valid", "values", "various").
Each value is the mean activation measured on training text, rounded.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if raw == END_OF_TEXT:
        return carry, 0.9
    piece = raw.strip()
    word = piece.lower()
    if word == "v":
        value = 0.7 if piece == "V" else 0.6
    elif word.startswith("va"):
        value = 0.1
    elif word.startswith("v"):
        value = 0.4 if piece[:1] == "V" else 0.3
    elif word.endswith("v"):
        value = 0.1
    else:
        value = 0.0
    return carry, value
